import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import type { MonitoringPasienDarurat } from '@/models/monitoring-pasien-darurat'
import { getMonitoringPasienDarurat } from '@/services/monitoring-pasien-darurat'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface MonitoringPasienDaruratProps {
  isReport?: boolean
  noreg?: string
}

const INITIAL_DATA: MonitoringPasienDarurat = {
  id: 0,
  noreg: '',
  dpjp: '',
  dokter_jaga: '',
  diagnosa: '',
  data: [],
}

const MonitoringPasienDarurat = ({
  isReport = false,
  noreg = '',
}: MonitoringPasienDaruratProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.monitoringPasienDarurat, noreg],
    queryFn: () => getMonitoringPasienDarurat(noreg),
    enabled: !!noreg,
  })

  const result = data?.response != null ? data?.response : INITIAL_DATA

  console.log('result ', result)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.dpjp === '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 1d' rev='02.2020'>
      <HeaderFormulir
        nama={pasien?.nama_pasien ?? ''}
        tanggalLahir={pasien?.tgl_lahir ?? ''}
        noRm={pasien?.no_rm ?? ''}
        nik={pasien?.nik ?? ''}
      >
        <h3>Monitoring Pasien Darurat</h3>
      </HeaderFormulir>

      <div className='p-2'>
        <div className='flex-1 px-2'>
          <Text k='Dokter Jaga IGD' v={result.dokter_jaga} />
          <Text k='DPJP' v={result.dpjp} />
          <Text k='Diagnosa' v={result.diagnosa} />

          <div className='p-2 mt-4'>
            {/* Header */}
            <div className='flex'>
              <SimpleColumn
                head
                name='No'
                className='p-[2px] text-xs flex-[0.2]'
              />
              <SimpleColumn
                head
                name='Tanggal & Jam'
                className='p-[2px] text-xs flex-[0.5]'
              />
              <SimpleColumn head name='TD' className='p-[2px] text-xs flex-1' />
              <SimpleColumn
                head
                name='NADI'
                className='p-[2px] text-xs flex-1'
              />
              <SimpleColumn
                head
                name='SUHU'
                className='p-[2px] text-xs flex-1'
              />
              <SimpleColumn head name='RR' className='p-[2px] text-xs flex-1' />
              <SimpleColumn
                head
                name='SpO2'
                className='p-[2px] text-xs flex-1'
              />
              <SimpleColumn
                head
                name='CATATAN (GCS, implementasi tindakan kedokteran dan implementasi tindakan keperawatan, kondisi pasien)'
                className='p-[2px] text-xs flex-1'
              />
              <SimpleColumn
                head
                isLast
                name='TINDAK LANJUT'
                className='p-[2px] text-xs flex-1'
              />
            </div>
            {/* Header */}
            {result.data.map((item, index) => (
              <div key={item.tanggal} className='flex'>
                <SimpleColumn
                  name={`${index + 1}`}
                  className='text-xs flex-[0.2]  border-t-0 p-[2px]'
                />
                <SimpleColumn
                  name={item.tanggal + ' WIB'}
                  className='text-xs flex-[0.5] border-t-0 p-[2px]'
                />
                <SimpleColumn
                  name={item.td}
                  className='text-left text-xs flex-1 border-t-0 p-[2px]'
                />
                <SimpleColumn
                  name={item.nadi}
                  className='text-left text-xs flex-1 border-t-0 p-[2px]'
                />
                <SimpleColumn
                  name={item.suhu}
                  className='text-left text-xs flex-1 border-t-0 p-[2px]'
                />
                <SimpleColumn
                  name={item.rr}
                  className='text-left text-xs flex-1 border-t-0 p-[2px]'
                />
                <SimpleColumn
                  name={item.spo2}
                  className='text-left text-xs flex-1 border-t-0 p-[2px]'
                />
                <SimpleColumn
                  name={item.catatan}
                  className='text-left text-xs flex-1 border-t-0 p-[2px]'
                />
                <SimpleColumn
                  isLast
                  name={item.tindak_lanjut}
                  className='text-left text-xs flex-1 border-t-0 p-[2px]'
                />
              </div>
            ))}
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default MonitoringPasienDarurat

const Text = ({ k, v }: { k: string; v: string }) => {
  return (
    <div className='flex items-center'>
      <div className='w-[250px]'>
        <p className='text-xs'>{k}</p>
      </div>
      <p className='text-xs'>: {v}</p>
    </div>
  )
}
