import { SimpleColumn } from '@/components/simple-column'

import {
  nyeriComponentTitles,
  nyeriLabelComfort,
  nyeriLabelFlacc,
  nyeriLabelNips,
  toNyeriImage,
  toNyeriText,
} from './nyeri-label-helper'

/** Data nyeri pengkajian awal (bentuk umum dari response backend). */
export interface TableNyeriData {
  noreg?: string
  metode?: string
  asesmen?: string
  pelayanan?: string
  skor_nyeri?: number
  hasil_nyeri?: number
  waktu_nyeri?: number
  penyebab?: string
  kualitas?: string
  penyebaran?: string
  keparahan?: string
  waktu?: string
  lokasi?: string
  n1?: number
  n2?: number
  n3?: number
  n4?: number
  n5?: number
  n6?: number
  n7?: number
  n8?: number
  n9?: number
}

const COMPONENT_METHODS = [
  'NIPS',
  'FLACGS',
  'FLACC',
  'CONFORT_SCALE',
  'COMFORT SCALE',
]

/**
 * Render pengkajian nyeri secara conditional sesuai metode:
 * - NIPS / FLACC / Comfort Scale -> tabel komponen berlabel (n1..n9)
 * - WONG_BAKER_FACE (default)    -> PQRST + skala + gambar wajah
 */
export default function TableNyeri({ data }: { data: TableNyeriData }) {
  const metode = (data.metode ?? 'WONG_BAKER_FACE').replace(/_/g, ' ')
  const isComponent = COMPONENT_METHODS.includes(data.metode ?? '')
  const skorNyeri = data.skor_nyeri ?? 0

  const nilai: number[] = [
    data.n1,
    data.n2,
    data.n3,
    data.n4,
    data.n5,
    data.n6,
    data.n7,
    data.n8,
    data.n9,
  ].map((v) => v ?? 0)

  let compTitles: string[] = []
  let compValues: string[] = []
  if (data.metode === 'NIPS') {
    compTitles = nyeriComponentTitles('NIPS')
    compValues = nilai
      .slice(0, 8)
      .map((v, i) => nyeriLabelNips(i, v))
  } else if (data.metode === 'FLACGS' || data.metode === 'FLACC') {
    compTitles = nyeriComponentTitles('FLACGS')
    compValues = nilai
      .slice(0, 5)
      .map((v, i) => nyeriLabelFlacc(i, v))
  } else if (
    data.metode === 'CONFORT_SCALE' ||
    data.metode === 'COMFORT SCALE'
  ) {
    compTitles = nyeriComponentTitles('CONFORT_SCALE')
    compValues = nilai
      .slice(0, 9)
      .map((v, i) => nyeriLabelComfort(i, v))
  }

  return (
    <div className='border border-black my-1 p-2'>
      <p className='flex-1 font-semibold'>Pengkajian Nyeri</p>
      <p className='text-xs'>
        Apakah Ada Nyeri/Tidak Nyaman ?{' '}
        {(data.hasil_nyeri ?? 0) > 0 ? 'Ya' : 'Tidak'}
      </p>

      {isComponent ? (
        <>
          <p className='text-xs font-bold'>
            Skala Nyeri {skorNyeri} — Metode: {metode}
          </p>
          <div className='flex'>
            {compTitles.map((t, i) => (
              <SimpleColumn
                key={t}
                head
                name={t}
                isLast={i === compTitles.length - 1}
              />
            ))}
          </div>
          <div className='flex'>
            {compValues.map((v, i) => (
              <SimpleColumn
                key={i}
                className='flex-1 text-xs border-t-0'
                name={v}
                isLast={i === compValues.length - 1}
              />
            ))}
          </div>
        </>
      ) : (
        <>
          <div className='flex'>
            <SimpleColumn head name='PENYEBAB' />
            <SimpleColumn head name='KUALITAS' />
            <SimpleColumn head name='PENYEBARAN' />
            <SimpleColumn head name='KEPARAHAN' />
            <SimpleColumn head name='WAKTU' />
            <SimpleColumn head name='LOKASI' isLast />
          </div>
          <div className='flex'>
            <SimpleColumn
              className='flex-1 text-xs border-t-0'
              name={data.penyebab}
            />
            <SimpleColumn
              className='flex-1 text-xs border-t-0'
              name={data.kualitas}
            />
            <SimpleColumn
              className='flex-1 text-xs border-t-0'
              name={data.penyebaran}
            />
            <SimpleColumn
              className='flex-1 text-xs border-t-0'
              name={data.keparahan}
            />
            <SimpleColumn
              className='flex-1 text-xs border-t-0'
              name={data.waktu}
            />
            <SimpleColumn
              className='flex-1 text-xs border-t-0'
              name={data.lokasi}
              isLast
            />
          </div>
          <div className='flex flex-col items-center mt-2'>
            <img
              src={toNyeriImage(skorNyeri)}
              alt='Skala Nyeri'
              className='h-[60px] w-[60px] object-contain'
            />
            <p className='text-xs'>
              Skala Nyeri {skorNyeri} Dengan Metode: {metode}
            </p>
            <p className='text-xs'>{toNyeriText(skorNyeri)}</p>
          </div>
        </>
      )}
    </div>
  )
}
