import clsx from 'clsx'

export const TextField = ({
  title = '',
  value = '',
  valueClass,
  titleClass,
}: {
  title: string
  value?: string
  valueClass?: string
  titleClass?: string
}) => {
  return (
    <div className='my-1'>
      <div className='flex items-start'>
        <div className={clsx('w-[150px] text-xs', titleClass)}>
          <p className='text-xs'>{title ?? ''}</p>
        </div>
        <div>
          <p className={clsx('text-xs', valueClass)}>
            {value != '' ? `: ${value}` : ''}
          </p>
        </div>
      </div>
    </div>
  )
}
