import { useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { getAllPengkajianUlangSuicide } from '@/services/pengkajian-ulang-suicide'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

import PengkajianUlangSuicideTable from './pengkajian-ulang-suicide-table'

interface ReportPengkajianUlangSuicideProps {
  isReport?: boolean
  noreg?: string
  no?: string
  kdBagian?: string
}

/* Level risiko — mirror Flutter report_pengkajian_ulang_bunuh_diri.dart */
const getLevelText = (total: number) => {
  if (total < 7) return 'RENDAH'
  if (total >= 7 && total <= 14) return 'SEDANG'
  return 'TINGGI'
}

const ReportPengkajianUlangSuicide = ({
  isReport,
  noreg,
  kdBagian,
}: ReportPengkajianUlangSuicideProps) => {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pengkajianUlangSuicide, noreg],
    queryFn: () => getAllPengkajianUlangSuicide(noreg!, kdBagian!),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const Default = () => {
    return (
      <LayoutBorderNo isReport={isReport} no='RM 23' rev='01.2020'>
        <div className='p-4 text-xs'>
          <HeaderFormulir
            nama={pasien?.nama_pasien ?? ''}
            tanggalLahir={pasien?.tgl_lahir ?? ''}
            noRm={pasien?.no_rm ?? ''}
            nik={pasien?.nik ?? ''}
          >
            <h3 className='text-xs font-bold text-center py-3'>
              PENGKAJIAN ULANG <br />
              RISIKO BUNUH DIRI DAN MELUKAI DIRI SENDIRI
            </h3>
          </HeaderFormulir>

          <div className='flex p-2'>
            <p className='text-xs text-black'>
              Tanggal Pengkajian : {formatDateTime(res[index].insert_dttm)}
            </p>
          </div>

          <div className='gap-4 border border-black p-1 mb-1'>
            <PengkajianUlangSuicideTable data={res[index]} />
            <p className='text-xs font-bold mt-2'>
              Total Skor Resiko Bunuh Diri : {res[index].total} - Level :{' '}
              {getLevelText(res[index].total)}
            </p>
          </div>

          {/* Tanda Tangan */}
          <div className='ml-4'>
            <div className='py-10' />
            <div className='flex items-end justify-between'>
              <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
                <p className='font-medium'>
                  Baturaja, {formatDateTime(res[index].insert_dttm)}
                </p>
                <p className='font-medium'>Perawat</p>
                {res[index].user ? (
                  <>
                    <QRCode
                      value={res[index].user}
                      className='h-[50px] w-[50px]'
                    />
                    <p>( {res[index].user} )</p>
                  </>
                ) : (
                  <div className='h-[50px]' />
                )}
              </div>
            </div>
          </div>
          {/* Tanda Tangan */}
        </div>
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {res != null &&
        res.length > 0 &&
        res.map((_, idx) => (
          <Button
            className='ml-2 my-2'
            variant={idx == index ? 'default' : 'outline'}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {idx + 1}
          </Button>
        ))}

      {res.length > 0 && <Default />}
    </>
  )
}

export default ReportPengkajianUlangSuicide
