import { cn } from '@/lib/utils'
import { ResikoJatuh } from '@/models/asesmen-keperawatan-rawat-inap'

type ResikoJatuhTableProps = {
  data: ResikoJatuh
}

const ResikoJatuhTable = ({ data }: ResikoJatuhTableProps) => {
  return (
    <div className='mb-2'>
      <p className='flex-1 font-semibold'>RESIKO JATUH</p>
      <div className='flex'>
        <div className='flex-1 border border-black border-r-0 border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>
            Pengkajian
          </p>
        </div>
        <div className='flex-[0.5] border border-black border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>Hasil</p>
        </div>
      </div>
      <Item
        k='Riwayat jatuh yang baru atau dalam 3 bulan terakhir?'
        v={splitStr(data.r_jatuh)}
      />
      <Item k='Diagnosis Medis Sekunder > 1' v={splitStr(data.diagnosis)} />
      <Item k='Alat bantu jalan' v={data.alat_bantu1} />
      <Item k='Menggunakan Infus' v={splitStr(data.terpasang_infuse)} />
      <Item k='Cara Berjalan / Berpindah' v={data.gaya_berjalan} />
      <Item k='Status Mental' v={data.status_mental} />
      <Item isLast k='Total Skor' v={`${data.total}`} />
    </div>
  )
}

export default ResikoJatuhTable

const Item = ({ k, v, isLast }: { k: string; v: string; isLast?: boolean }) => {
  return (
    <div className='flex'>
      <div
        className={cn(
          'flex-1 border border-black border-r-0  p-2 border-b-[0] ',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{k}</p>
      </div>
      <div
        className={cn(
          'flex-[0.5] border border-black p-2 border-b-[0]',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{v}</p>
      </div>
    </div>
  )
}

function splitStr(str: string) {
  return str.split(',')[0]
}
