import { Activity, HeartPulse, Stethoscope } from 'lucide-react'

import { cn } from '@/lib/utils'

interface RingkasanPemetaanProps {
  diagnosa: number
  slki: number
  siki: number
}

const CARDS = [
  {
    key: 'diagnosa' as const,
    label: 'Diagnosa',
    sub: 'SDKI',
    icon: Stethoscope,
    chip: 'bg-sky-50 text-sky-600 ring-sky-100',
  },
  {
    key: 'slki' as const,
    label: 'Luaran',
    sub: 'SLKI',
    icon: Activity,
    chip: 'bg-emerald-50 text-emerald-600 ring-emerald-100',
  },
  {
    key: 'siki' as const,
    label: 'Intervensi',
    sub: 'SIKI',
    icon: HeartPulse,
    chip: 'bg-violet-50 text-violet-600 ring-violet-100',
  },
]

/**
 * Kartu ringkasan jumlah diagnosa (SDKI) dan jumlah kode unik
 * luaran (SLKI) serta intervensi (SIKI) yang terpetakan.
 */
export default function RingkasanPemetaan({
  diagnosa,
  slki,
  siki,
}: RingkasanPemetaanProps) {
  const values = { diagnosa, slki, siki }

  return (
    <div className='grid grid-cols-1 gap-3 sm:grid-cols-3'>
      {CARDS.map((card) => {
        const Icon = card.icon

        return (
          <div
            key={card.key}
            className='flex items-center gap-3 rounded-xl border border-slate-200 bg-white p-3 shadow-sm transition-shadow hover:shadow-md'
          >
            <span
              className={cn(
                'flex size-9 shrink-0 items-center justify-center rounded-lg ring-1 ring-inset',
                card.chip,
              )}
            >
              <Icon className='size-4' />
            </span>
            <div className='min-w-0'>
              <p className='text-[10px] font-medium uppercase tracking-wider text-slate-400'>
                {card.label} · {card.sub}
              </p>
              <p className='text-xl font-bold tabular-nums text-slate-800'>
                {values[card.key]}
              </p>
            </div>
          </div>
        )
      })}
    </div>
  )
}
