export default function useReportResume(
  noreg: string,
  kdBagian: string,
  tipeAsesmen: string,
) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.resumeMedis, noreg],
    queryFn: () => getResumeMedis(noreg!),
    enabled: !!noreg,
  })

  const resumeRanap = useQuery({
    queryKey: ['resume-ranap', noreg],
    queryFn: () => getResumeRanap(noreg, kdBagian, tipeAsesmen),
    enabled: !!noreg,
  })

  // const resume = useQuery({
  //   queryKey: ['resume', noreg],
  //   queryFn: () => getResume(noreg, kdBagian),
  //   enabled: !!noreg,
  // })

  const resumeRanapAll = useQuery({
    queryKey: ['resume-ranap-all', noreg],
    queryFn: () => getAllResumeRanap(noreg, kdBagian, tipeAsesmen),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : initResumeMedis
  const resRanap =
    resumeRanap.data != null ? resumeRanap.data.response : initRingkasanPulang
  // const resResume = resume.data != null ? resume.data.response : initResume

  return {
    res,
    resRanap,
    // resResume,
    isLoading,
    isError,
    resumeRanapAll,
  }
}
