import { AllNomorOperasi, DataOperasiByNomor } from '@/models/all-nomor'
import { LaporanTindakanModel } from '@/models/laporan-tindakan'
import type { LaporanOperasi, Response } from '@/type'

import { get, post } from './api-2'

const getLaporOperasi = async ({
  noreg,
  kd_bagian,
}: {
  noreg: string
  kd_bagian: string
}): Promise<Response<LaporanOperasi>> => {
  const response = await get(`/v1/laporan-operasi/${noreg}/${kd_bagian}`)

  return response.data
}

const getLaporanTindakan = async ({
  no_reg,
  kd_bagian,
}: {
  no_reg: string
  kd_bagian: string
}): Promise<Response<LaporanTindakanModel>> => {
  const response = await post(`/v1/report-laporan-tindakan`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}

const getAllNomorOperasi = async ({
  no_reg,
}: {
  no_reg: string
}): Promise<Response<AllNomorOperasi[]>> => {
  const response = await post(`/v2/nomor-operasi-all`, {
    no_reg,
  })

  return response.data
}

const getPembedahanByNomor = async ({
  no_reg,
  nomor,
  no_rm,
}: {
  no_reg: string
  nomor: string
  no_rm: string
}): Promise<Response<DataOperasiByNomor>> => {
  const response = await post(`/v2/pembedahan-operasi-by-nomor`, {
    no_reg,
    nomor,
    no_rm,
  })

  return response.data
}

export {
  getLaporOperasi,
  getLaporanTindakan,
  getAllNomorOperasi,
  getPembedahanByNomor,
}
