import {
  IntervensiSuicide,
  PengkajianUlangSuicide,
} from '@/models/pengkajian-ulang-suicide'
import type { Response } from '@/type'

import { post } from './api-2'

const getAllPengkajianUlangSuicide = async (
  no_reg: string,
  kd_bagian: string,
): Promise<Response<PengkajianUlangSuicide[]>> => {
  const response = await post(`/v1/pengkajian-ulang-suicide/all`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}

const getAllIntervensiSuicide = async (
  no_reg: string,
  kd_bagian: string,
): Promise<Response<IntervensiSuicide[]>> => {
  const response = await post(`/v1/intervensi-suicide/all`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}

export { getAllPengkajianUlangSuicide, getAllIntervensiSuicide }
