import clsx from 'clsx'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { LembarMasukKeluarResponse } from '@/models/lembar-masuk-keluar'
import { getLembarMasukKeluar } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { formatDate } from '@/utils/formatDate'

// import { DiagnosaTable } from './diagnosa-table'
// import { TindakanTable } from './tindakan-table'
import { TextField } from './text-field'

interface LembarMasukDanKeluarProps {
  isReport?: boolean
  noreg?: string
}

const INITIAL_DATA: LembarMasukKeluarResponse = {
  pasien: {
    nama: '',
    alamat: '',
    jenis_kelamin: '',
    agama: '',
    kebangsaan: '',
    suku: '',
    pekerjaan: '',
    nama_keluarga: '',
    nama_ayah: '',
    nama_ibu: '',
    status: '',
    pendidikan: '',
    hp: '',
    tanggal_masuk: '',
    tanggal_keluar: '',
    jam_keluar: '',
    rujuk_dari: '',
    lama_rawat: '',
    dokter: '',
    spesialisasi: '',
    pembiayaan: '',
    bagian: '',
    kelas: '',
    umur: '',
    jumlah_dirawat: '',
    keadaan_keluar: '',
    keterangan_keluar: '',
    jam_masuk: '',
  },
  diagnosa: [],
  tindakan: [],
  asesmen: {
    kd_bagian: '',
    pelayanan: '',
    noreg: '',
    kondisi_pulang: '',
    cara_keluar: '',
    keluhan_utama: '',
    nama_dokter: '',
  },
}

const LembarMasukDanKeluar = ({
  isReport = false,
  noreg = '',
}: LembarMasukDanKeluarProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: ['lembar-keluar-masuk', noreg],
    queryFn: () => getLembarMasukKeluar(noreg),
    enabled: !!noreg,
  })

  const result = data?.response != null ? data?.response : INITIAL_DATA

  console.log('result ', result)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result?.pasien.nama == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 1' rev='03.2020'>
      <HeaderFormulir
        nama={pasien?.nama_pasien ?? ''}
        tanggalLahir={pasien?.tgl_lahir ?? ''}
        noRm={pasien?.no_rm ?? ''}
        nik={pasien?.nik ?? ''}
      >
        <h3>LEMBAR MASUK DAN KELUAR</h3>
      </HeaderFormulir>

      <div className='flex -mt-1'>
        <div className='flex flex-col flex-1'>
          <Box title='ALAMAT' description={result.pasien.alamat} />
          <Box title='AGAMA/KEPERCAYAAN' description={result.pasien.agama} />

          <div className='min-h-[50px] px-2 border border-black border-l-0 w-full border-t-0'>
            <p className='text-sm'>KEBANGSAAN : {result.pasien.kebangsaan}</p>
            <p className='text-sm'>SUKU : {result.pasien.suku}</p>
          </div>

          <Box title='PEKERJAAN' description={result.pasien.pekerjaan} />

          <div className='min-h-[50px] px-2 border border-black border-l-0 w-full border-t-0'>
            <p className='text-xs'>
              Nama Keluarga / Wali terdekat / alamatnya:
            </p>

            <p className='text-xs'>{result.pasien.nama_ibu}</p>
            <p className='text-xs'>No HP: {result.pasien.hp}</p>
          </div>

          <div className='min-h-[50px] px-2 border border-black border-l-0 w-full border-t-0 flex items-start justify-between'>
            <div className='flex-1'>
              <p className='text-xs'>Nama Ayah/Suami: </p>
              <p className='text-xs'>Umur : </p>
              <p className='text-xs'>Pekerjaan : </p>
              <p className='text-xs'>No.HP : </p>
            </div>
            <div className='border border-t-0 border-r-0 border-black border-b-0 flex-[0.3] w-full h-full px-1'>
              <p className='text-xs min-w-[100px]'>Pembayaran </p>
              <p className='text-xs'>{result.pasien.pembiayaan}</p>
            </div>
          </div>

          <div className='min-h-[50px] px-2 border border-black border-l-0 w-full border-t-0 flex items-start justify-between'>
            <div className='flex-1'>
              <p className='text-xs'>Nama Ibu/Istri :</p>
              <p className='text-xs'>Umur : </p>
              <p className='text-xs'>Pekerjaan : </p>
              <p className='text-xs'>No.HP : </p>
            </div>
            {/* <div className='border border-t-0 border-r-0 border-black border-b-0 flex-[0.3] w-full h-full px-1'>
              <p className='text-xs min-w-[100px]'>Kasus Polisi </p>
            </div> */}
          </div>

          <div className='min-h-[50px] px-2 border border-black border-l-0 w-full border-t-0'>
            <p className='text-xs text-center'>SPESIALISASI</p>
            <p className='text-xs text-center'>{result.pasien.spesialisasi}</p>
          </div>
          <div className='min-h-[50px]  w-full border-t-0 flex flex-1'>
            <div className='min-h-[50px] px-2 border border-black border-l-0 w-full border-t-0'>
              <p className='text-xs'>RUANG</p>
              <p className='text-xs'>
                {result.pasien.bagian.split('-')[0]}-
                {result.pasien.bagian.split('-')[1]}
              </p>
            </div>
            <div className='min-h-[50px] px-2 border border-black border-l-0 w-full border-t-0'>
              <p className='text-xs'>Kelas</p>
              <p className='text-xs'>{result.pasien.kelas}</p>
            </div>
            <div className='min-h-[50px] px-2 border border-black border-l-0 w-full border-t-0'>
              <p className='text-xs'>Sebab Dirawat</p>
              <p className='text-xs'>{result.asesmen.keluhan_utama}</p>
            </div>
          </div>
        </div>
        <div className='flex flex-col flex-1'>
          <Box
            cn='border-r-0'
            title='Dirawat di RS yang ke:'
            description={result.pasien.jumlah_dirawat}
          />
          <Box
            cn='border-r-0'
            title='STATUS PERKAWINAN'
            description={result.pasien.status}
          />
          <Box
            cn='border-r-0'
            title='JENIS KELAMIN'
            description={result.pasien.jenis_kelamin}
          />
          <Box
            cn='border-r-0'
            title='PENDIDIKAN'
            description={result.pasien.pendidikan}
          />
          <Box
            cn='border-r-0'
            title='UMUR WAKTU MASUK'
            description={result.pasien.umur}
          />
          <Box
            cn='border-r-0'
            title='RUJUKAN DARI'
            description={result.pasien.rujuk_dari}
          />
          <Box
            cn='border-r-0'
            title='TANGGAL MASUK'
            description={`${formatDate(result.pasien.tanggal_masuk)} Pukul : ${result.pasien.jam_masuk} WIB`}
          />
          <Box
            cn='border-r-0'
            title='TANGGAL KELUAR'
            description={`${formatDate(result.pasien.tanggal_keluar)} Pukul : ${result.pasien.jam_keluar} WIB`}
          />
          <Box
            cn='border-r-0'
            title='LAMANYA DIRAWAT'
            description={`${result.pasien.lama_rawat} hari`}
          />
          <Box
            cn='border-r-0'
            title='DPJP'
            description={result.asesmen.nama_dokter}
          />
        </div>
        <div className='flex flex-[0.5] flex-col border border-black border-t-0 border-r-0 border-b-0'></div>
      </div>

      <div className='flex'>
        <div className='flex flex-[2] flex-col'>
          <div className='px-2 mb-4'>
            <TextField title='Diagnosa' />
            {/* <DiagnosaTable data={result.diagnosa} /> */}
            {result.diagnosa.map((item, index) => (
              <p className='text-xs font-medium' key={index}>
                {index + 1}. {item.diagnosa} - {item.description}
              </p>
            ))}
            <TextField title='Operasi/Tindakan' />
            {result.tindakan.map((item, index) => (
              <p className='text-xs font-medium' key={index}>
                {index + 1}. {item.kode2} - {item.description}
              </p>
            ))}
            {/* <TindakanTable data={result.tindakan} /> */}
          </div>
          <div className='px-2 border border-black w-full border-x-0'>
            <p className='text-xs'>CATATAN</p>
          </div>
          <div className='min-h-[50px]  w-full border-t-0 flex flex-1'>
            <div className='min-h-[50px] px-2 border border-black border-x-0 w-full border-t-0'>
              <p className='text-xs'>KEADAAN KELUAR</p>
              <p className='text-xs'>{result.pasien.keadaan_keluar}</p>
            </div>
            <div className='min-h-[50px] px-2 border border-black border-x-0 w-full border-t-0'>
              <p className='text-xs'>CARA KELUAR</p>
              <p className='text-xs'>{result.pasien.keterangan_keluar}</p>
            </div>
          </div>
        </div>
        <div className='flex flex-[0.5] flex-col border border-black border-t-0 border-r-0'></div>
      </div>
      <div className='mb-4' />

      <div className='w-full text-center items-center flex flex-col gap-4 mb-4'>
        {result.asesmen.nama_dokter != '' ? (
          <>
            <p className='text-xs font-medium'>TANDA TANGAN DAN NAMA DOKTER</p>
            {result.asesmen.nama_dokter != '' ? (
              <QRCode
                value={result.asesmen.nama_dokter}
                className='h-[50px] w-[50px]'
              />
            ) : (
              <div className='h-[100px]' />
            )}
            <p className='text-xs'>( {result.asesmen.nama_dokter} )</p>
          </>
        ) : (
          <div className='h-[100px]' />
        )}
      </div>
    </LayoutBorderNo>
  )
}

export default LembarMasukDanKeluar

const Box = ({
  title,
  description,
  cn = '',
}: {
  title: string
  description: string
  hasChild?: boolean
  children?: React.ReactNode
  cn?: string
}) => {
  return (
    <div
      className={clsx(
        'min-h-[50px] px-2 border border-black border-l-0 w-full border-t-0',
        cn,
      )}
    >
      <p className='text-xs'>{title}</p>
      <p className='text-xs'>{description}</p>
    </div>
  )
}
