import { cn } from '@/lib/utils'

/** Kode referensi (SDKI/SLKI/SIKI) dengan gaya monospace. */
export function KodeBadge({
  code,
  className,
}: {
  code: string
  className?: string
}) {
  return (
    <span
      className={cn(
        'inline-flex shrink-0 items-center rounded-md bg-slate-100 px-1.5 py-0.5 font-mono text-[10px] font-medium text-slate-600 ring-1 ring-inset ring-slate-200',
        className,
      )}
    >
      {code}
    </span>
  )
}

/** Chip label generik (kategori, ekspektasi, dsb). */
export function Chip({
  children,
  className,
}: {
  children: React.ReactNode
  className?: string
}) {
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[10px] font-medium ring-1 ring-inset',
        className,
      )}
    >
      {children}
    </span>
  )
}

/** Counter kecil untuk jumlah luaran/intervensi pada daftar. */
export function CountPill({
  label,
  value,
  className,
}: {
  label: string
  value: number
  className?: string
}) {
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[10px] font-medium tabular-nums ring-1 ring-inset',
        className,
      )}
    >
      <span className='opacity-70'>{label}</span>
      {value}
    </span>
  )
}
