import { useState } from 'react'

import { createFileRoute } from '@tanstack/react-router'

import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
// import {
//   Select,
//   SelectContent,
//   SelectGroup,
//   SelectItem,
//   SelectTrigger,
//   SelectValue,
// } from '@/components/ui/select'
import { getResumeRanap } from '@/services/rekam-medis'
import { constants } from '@/utils/constants'

export const Route = createFileRoute('/resume-rajal')({
  component: ResumeRajal,
})

function ResumeRajal() {
  const [noreg, setNoreg] = useState<string>('')
  const [hasResume, setHasResume] = useState(false)

  async function onCari(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()

    if (noreg == '') {
      alert('Nomor Registrasi wajib diisi!')
      return
    }
    const res = await getResumeRanap(noreg, 'IGD001', '')
    const data = res.response != null ? res.response : null

    if (data != null) {
      if (data.indikasi_ranap.keluhan_utama != '') {
        setHasResume(true)
      }
    }
  }

  return (
    <div className='min-h-screen max-width flex flex-col items-center justify-center'>
      <div className='p-4  w-[500px] border shadow-md rounded-md flex flex-col items-center justify-center'>
        <h1 className='text-2xl font-medium text-center mb-4'>
          RESUME POLI UGD
        </h1>
        {/* Select No Reg */}
        <form onSubmit={onCari} className='w-full'>
          <Input
            placeholder='Nomor Registrasi'
            className='mb-4 w-full'
            value={noreg}
            onChange={(e) => setNoreg(e.target.value)}
          />
          {/* Select No Reg */}
          <Button className='w-full' type='submit'>
            CARI
          </Button>
        </form>
        {hasResume && (
          <div className='flex items-center gap-4'>
            <a
              className='mt-4 underline'
              target='_blank'
              href={`http://192.168.0.5:8383/report/resume-gawat-darurat-rekam-medis?noreg="${noreg}"&no=RM.%20&kd_bagian="IGD001"`}
              onClick={() => setHasResume(false)}
            >
              Lihat Resume
            </a>
            <a
              className='mt-4 underline'
              target='_blank'
              href={`http://192.168.0.5:8383/report/resume-gawat-darurat-v2-rekam-medis?noreg="${noreg}"&no=RM.%20&kd_bagian="IGD001"`}
              onClick={() => setHasResume(false)}
            >
              Lihat Resume v2
            </a>
          </div>
        )}
      </div>
      <p className='text-xs mt-4'>v{constants.version}</p>
      <p className='text-xs mt-4 italic'>
        *v2 adalah resume yang sudah di edit di rme
      </p>
    </div>
  )
}
