import type { KriteriaHasil } from '@/models/sdki-slki'

/**
 * Memecah string kode yang dipisahkan koma menjadi array yang sudah di-`trim`.
 *
 * Penting: backend memakai `strings.Split(mapping, ",")` tanpa `TrimSpace`,
 * sehingga master data seperti `"D.0001, D.0002"` gagal diresolusi di sisi Go.
 * Parsing di klien ini memakai `trim()` agar kode tetap tampil benar.
 */
export function parseCodes(value?: string | null): string[] {
  if (!value) return []

  const codes = value
    .split(',')
    .map((code) => code.trim())
    .filter((code) => code.length > 0)

  return Array.from(new Set(codes))
}

/** Membuang kriteria hasil yang tidak punya nama (data lama/parsial). */
export function kriteriaTerisi(
  items?: KriteriaHasil[] | null,
): KriteriaHasil[] {
  if (!items) return []

  return items.filter((item) => (item.nama ?? '').trim().length > 0)
}
