function toWaktu(index: number, ket: string, data: ApgarScore[]): string {
  const current = data.filter(
    (item) => item.waktu.toLowerCase() == ket.toLowerCase(),
  )[0]

  if (current) {
    switch (index) {
      case 0:
        return `${current.jantung}`
      case 1:
        return `${current.nafas}`
      case 2:
        return `${current.otot}`
      case 3:
        return `${current.refleksi}`
      case 4:
        return `${current.warna_kulit}`
      case 5:
        return `${current.total}`
      default:
        return ''
    }
  }

  return ''
}
