import { Database, LayoutGrid, Search, Wrench, X } from 'lucide-react'

import { useEffect, useMemo, useState } from 'react'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { cn } from '@/lib/utils'
import type {
  DeskripsiSIKI,
  DiagnosaKeperawatan,
  LuaranSLKI,
  MappingNormalized,
  SDKISLKIResponse,
} from '@/models/sdki-slki'
import {
  getDaftarDiagnosaKeperawatan,
  getMappingDiagnosa,
} from '@/services/sdki-slki'
import { constants } from '@/utils/constants'

import { IntervensiCard, LuaranCard } from './components/detail-pemetaan'
import { Chip, CountPill, KodeBadge } from './components/kode-badge'
import RingkasanPemetaan from './components/ringkasan-pemetaan'
import { parseCodes } from './utils'

/**
 * Menormalkan response pemetaan.
 *
 * Backend membalas `{ metadata }` tanpa `response` bila kode tidak ditemukan,
 * dan `slki`/`siki` berupa `null` saat slice Go kosong.
 */
function normalizeMapping(
  payload: SDKISLKIResponse | undefined,
): MappingNormalized | null {
  if (!payload || !payload.diagnosa?.kode) return null

  return {
    diagnosa: payload.diagnosa,
    slki: payload.slki ?? [],
    siki: payload.siki ?? [],
  }
}

export default function SdkiSlki() {
  const [search, setSearch] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  const [selected, setSelected] = useState('')

  /** Cache pemetaan lengkap per kode diagnosa (dimuat saat baris diklik). */
  const [details, setDetails] = useState<Record<string, MappingNormalized>>({})
  const [loadingKode, setLoadingKode] = useState('')
  const [detailError, setDetailError] = useState('')

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 400)
    return () => clearTimeout(timer)
  }, [search])

  /**
   * Master diagnosa keperawatan beserta kode SLKI/SIKI.
   * Endpoint publik + di-cache 24 jam, jadi cukup satu permintaan.
   */
  const {
    data: master,
    isLoading: masterLoading,
    isError: masterError,
  } = useQuery({
    queryKey: [constants.queryKey.sdkiSlki.list],
    queryFn: getDaftarDiagnosaKeperawatan,
    staleTime: Infinity,
  })

  const daftarDiagnosa: DiagnosaKeperawatan[] = useMemo(
    () => master?.response ?? [],
    [master],
  )

  const diagnosaTampil = useMemo(() => {
    const keyword = debouncedSearch.trim().toLowerCase()
    if (!keyword) return daftarDiagnosa

    return daftarDiagnosa.filter(
      (item) =>
        item.kode.toLowerCase().includes(keyword) ||
        item.judul.toLowerCase().includes(keyword),
    )
  }, [daftarDiagnosa, debouncedSearch])

  /**
   * Ringkasan dihitung dari master, memakai `trim()` sendiri karena backend
   * memisah kode dengan koma tanpa menghapus spasi.
   */
  const ringkasan = useMemo(
    () => ({
      diagnosa: daftarDiagnosa.length,
      slki: new Set(daftarDiagnosa.flatMap((d) => parseCodes(d.slki))).size,
      siki: new Set(daftarDiagnosa.flatMap((d) => parseCodes(d.siki))).size,
    }),
    [daftarDiagnosa],
  )

  /** Memuat pemetaan lengkap untuk diagnosa yang dipilih. */
  useEffect(() => {
    if (!selected || details[selected]) return

    let cancelled = false

    async function run() {
      setLoadingKode(selected)
      setDetailError('')

      try {
        const res = await getMappingDiagnosa(selected)
        const data = normalizeMapping(res?.response)

        if (cancelled) return

        if (!data) {
          setDetailError('Pemetaan kode ini tidak ditemukan.')
          return
        }

        setDetails((prev) => ({ ...prev, [selected]: data }))
      } catch {
        if (!cancelled) {
          setDetailError('Gagal memuat pemetaan. Silakan coba lagi.')
        }
      } finally {
        if (!cancelled) setLoadingKode('')
      }
    }

    run()

    return () => {
      cancelled = true
    }
  }, [selected, details])

  const detail = selected ? details[selected] : undefined
  const isLoadingDetail = selected !== '' && loadingKode === selected

  const luaranList: LuaranSLKI[] = detail?.slki ?? []
  const intervensiList: DeskripsiSIKI[] = detail?.siki ?? []

  return (
    <div className='overflow-hidden rounded-xl border border-slate-200 bg-slate-50/60 shadow-sm'>
      {/* ============ TOOLBAR ============ */}
      <header className='border-b border-slate-200 bg-white'>
        <div className='flex flex-col gap-3 p-4 lg:flex-row lg:items-center lg:justify-between'>
          <div className='min-w-0'>
            <h1 className='truncate text-base font-semibold text-slate-800'>
              Pemetaan SDKI · SLKI · SIKI
            </h1>
            <p className='mt-0.5 flex items-center gap-1.5 text-[11px] text-slate-500'>
              <Database className='size-3' />
              Standar Diagnosis, Luaran &amp; Intervensi Keperawatan Indonesia
            </p>
          </div>

          <div className='relative w-full lg:w-80'>
            <Search className='absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-slate-400' />
            <Input
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder='Cari kode atau judul diagnosa...'
              className='h-9 border-slate-200 bg-slate-50 pl-9 pr-8 text-xs placeholder:text-slate-400 focus-visible:bg-white'
            />
            {search && (
              <button
                type='button'
                onClick={() => setSearch('')}
                className='absolute right-2 top-1/2 -translate-y-1/2 rounded p-0.5 text-slate-400 transition-colors hover:bg-slate-200 hover:text-slate-600'
                aria-label='Bersihkan pencarian'
              >
                <X className='size-3.5' />
              </button>
            )}
          </div>
        </div>

        <div className='border-t border-slate-100 p-4'>
          <RingkasanPemetaan
            diagnosa={ringkasan.diagnosa}
            slki={ringkasan.slki}
            siki={ringkasan.siki}
          />
        </div>
      </header>

      {/* ============ SPLIT PANE ============ */}
      <div className='flex flex-col lg:flex-row'>
        {/* -------- Master diagnosa -------- */}
        <aside className='flex w-full shrink-0 flex-col border-b border-slate-200 bg-white lg:w-[min(24rem,38%)] lg:border-b-0 lg:border-r'>
          <div className='flex items-center justify-between border-b border-slate-100 px-3 py-2.5'>
            <span className='text-[10px] font-semibold uppercase tracking-wider text-slate-500'>
              Diagnosa (SDKI)
            </span>
            <span className='text-[10px] tabular-nums text-slate-400'>
              {diagnosaTampil.length} / {daftarDiagnosa.length}
            </span>
          </div>

          <div className='max-h-[calc(100vh-20rem)] min-h-[16rem] flex-1 overflow-y-auto'>
            {masterLoading && <Loading className='h-40' />}
            {masterError && <Error className='h-40' />}

            {!masterLoading && !masterError && diagnosaTampil.length === 0 && (
              <EmptyPlaceholder message='Diagnosa tidak ditemukan.' />
            )}

            <ul className='divide-y divide-slate-100'>
              {diagnosaTampil.map((item) => {
                const isActive = selected === item.kode
                const jumlahSlki = parseCodes(item.slki).length
                const jumlahSiki = parseCodes(item.siki).length

                return (
                  <li key={item.kode}>
                    <button
                      type='button'
                      onClick={() => setSelected(item.kode)}
                      className={cn(
                        'group relative flex w-full flex-col gap-1.5 px-3 py-2.5 text-left transition-colors',
                        isActive ? 'bg-primaryColor/5' : 'hover:bg-slate-50',
                      )}
                    >
                      {/* Aksen kiri untuk baris aktif */}
                      <span
                        className={cn(
                          'absolute inset-y-0 left-0 w-0.5 transition-colors',
                          isActive ? 'bg-primaryColor' : 'bg-transparent',
                        )}
                      />

                      <div className='flex items-center gap-2'>
                        <KodeBadge code={item.kode} />
                        {jumlahSlki + jumlahSiki === 0 && (
                          <Chip className='bg-slate-50 text-slate-500 ring-slate-200'>
                            belum dipetakan
                          </Chip>
                        )}
                      </div>

                      <span
                        className={cn(
                          'text-xs leading-snug',
                          isActive
                            ? 'font-semibold text-primaryColor'
                            : 'font-medium text-slate-700',
                        )}
                      >
                        {item.judul}
                      </span>

                      <div className='flex flex-wrap gap-1'>
                        <CountPill
                          label='SLKI'
                          value={jumlahSlki}
                          className='bg-emerald-50 text-emerald-700 ring-emerald-100'
                        />
                        <CountPill
                          label='SIKI'
                          value={jumlahSiki}
                          className='bg-violet-50 text-violet-700 ring-violet-100'
                        />
                      </div>
                    </button>
                  </li>
                )
              })}
            </ul>
          </div>
        </aside>

        {/* -------- Detail pemetaan -------- */}
        <section className='min-w-0 flex-1 bg-slate-50/60'>
          {!selected && (
            <EmptyPlaceholder message='Pilih salah satu diagnosa di sebelah kiri untuk melihat pemetaan SLKI dan SIKI.' />
          )}

          {selected && isLoadingDetail && <Loading className='h-60' />}

          {selected && !isLoadingDetail && detailError && (
            <EmptyPlaceholder message={detailError}>
              <Button
                type='button'
                variant='outline'
                size='sm'
                onClick={() => setSelected('')}
              >
                Tutup
              </Button>
            </EmptyPlaceholder>
          )}

          {selected && !isLoadingDetail && detail && (
            <div className='space-y-3 p-4'>
              {/* Header diagnosa */}
              <div className='rounded-xl border border-slate-200 bg-white p-4 shadow-sm'>
                <div className='flex items-start justify-between gap-3'>
                  <div className='min-w-0'>
                    <div className='flex flex-wrap items-center gap-2'>
                      <KodeBadge code={detail.diagnosa.kode} />
                      <h2 className='text-sm font-bold text-slate-800'>
                        {detail.diagnosa.judul}
                      </h2>
                    </div>
                    {detail.diagnosa.defenisi && (
                      <p className='mt-1.5 text-[11px] italic leading-relaxed text-slate-500'>
                        {detail.diagnosa.defenisi}
                      </p>
                    )}
                  </div>

                  <button
                    type='button'
                    onClick={() => setSelected('')}
                    className='shrink-0 rounded-lg p-1 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600'
                    aria-label='Tutup detail'
                  >
                    <X className='size-4' />
                  </button>
                </div>

                {/* Kode pemetaan mental */}
                <div className='mt-3 grid grid-cols-1 gap-2 border-t border-slate-100 pt-3 sm:grid-cols-2'>
                  <div className='flex items-start gap-2'>
                    <span className='mt-0.5 text-[10px] font-semibold uppercase tracking-wider text-slate-400'>
                      Kode SLKI
                    </span>
                    <span className='font-mono text-[11px] text-slate-600'>
                      {parseCodes(detail.diagnosa.slki).join(', ') || '-'}
                    </span>
                  </div>
                  <div className='flex items-start gap-2'>
                    <span className='mt-0.5 text-[10px] font-semibold uppercase tracking-wider text-slate-400'>
                      Kode SIKI
                    </span>
                    <span className='font-mono text-[11px] text-slate-600'>
                      {parseCodes(detail.diagnosa.siki).join(', ') || '-'}
                    </span>
                  </div>
                </div>
              </div>

              {/* Tab luaran & intervensi */}
              <Tabs defaultValue='luaran'>
                <TabsList className='h-9 w-full justify-start bg-white p-1 shadow-sm sm:w-auto'>
                  <TabsTrigger
                    value='luaran'
                    className='gap-1.5 text-xs data-[state=active]:text-primaryColor'
                  >
                    <LayoutGrid className='size-3.5' />
                    Luaran (SLKI)
                    <span className='rounded-full bg-emerald-50 px-1.5 text-[10px] tabular-nums text-emerald-700'>
                      {luaranList.length}
                    </span>
                  </TabsTrigger>
                  <TabsTrigger
                    value='intervensi'
                    className='gap-1.5 text-xs data-[state=active]:text-primaryColor'
                  >
                    <Wrench className='size-3.5' />
                    Intervensi (SIKI)
                    <span className='rounded-full bg-violet-50 px-1.5 text-[10px] tabular-nums text-violet-700'>
                      {intervensiList.length}
                    </span>
                  </TabsTrigger>
                </TabsList>

                <TabsContent value='luaran' className='space-y-2'>
                  {luaranList.length === 0 && (
                    <EmptyPlaceholder message='Luaran belum tersedia untuk diagnosa ini.' />
                  )}
                  {luaranList.map((luaran) => (
                    <LuaranCard key={luaran.kode_slki} luaran={luaran} />
                  ))}
                </TabsContent>

                <TabsContent value='intervensi' className='space-y-2'>
                  {intervensiList.length === 0 && (
                    <EmptyPlaceholder message='Intervensi belum tersedia untuk diagnosa ini.' />
                  )}
                  {intervensiList.map((intervensi) => (
                    <IntervensiCard
                      key={intervensi.kode}
                      intervensi={intervensi}
                    />
                  ))}
                </TabsContent>
              </Tabs>
            </div>
          )}
        </section>
      </div>
    </div>
  )
}
