import type { RujukanPasienReport } from '@/models/rujukan-pasien'
import type { Response } from '@/type'

import { post } from './api-2'

const getReportRujukanPasien = async ({
  noreg,
  no_rm,
}: {
  noreg: string
  no_rm: string
}): Promise<Response<RujukanPasienReport>> => {
  const response = await post(`/v1/rujukan-pasien/report-web`, { noreg, no_rm })

  return response.data
}

export { getReportRujukanPasien }
