import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { PersiapanOperasiModel } from '@/models/persiapan-operasi'
import { getReportPersiapanOperasi } from '@/services/persiapan-operasi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportPersiapanOperasiProps {
  isReport?: boolean
  noreg?: string
  noRm?: string
  kdBagian?: string
}

const init: PersiapanOperasiModel = {
  id: 0,
  insert_dttm: '',
  noreg: '',
  insert_user_id: '',
  pelayanan: '',
  kd_bagian: '',
  tanggal_operasi: '',
  rencana_operasi_pukul: '',
  dokter_ahli_bedah: '',
  diagnosa_pra_bedah: '',
  rencana_tindakan: '',
  dokter_anastesi: '',
  visite_pra_anastesi: '',
  jenis_narcose: '',
  visite_pra_bedah: '',
  suhu: 0,
  nadi: '',
  rr: '',
  td: '',
  bb: '',
  tb: '',
  spo2: '',
  riwayat_alergi_obat: '',
  riwayat_penyakit_lain: '',
  alkes_terpasang: '',
  dicukur_tanggal: '',
  dicukur_oleh: '',
  persiapan_transfusi: '',
  puasa: '',
  diberikan_premedikasi: '',
  protease_dilepas: '',
  perhiasan_pasien_dilepas: '',
  pengosongan_kandung_kemih: '',
  lembar_visite_pra_anestesi: '',
  surat_ijin_operasi: '',
  surat_ijin_anastesi: '',
  berkas_rm: '',
  rontgen: '',
  usg: '',
  ekg: '',
  laboratorium: '',
  lain_lain: '',
  perawat_ok: '',
  penandaan_lokasi_operasi: '',
  nama_dokter: '',
  nama_dokter_anastesi: '',
  nama_perawat_ok: '',
  nama_perawat: '',
}

const _v = (val: string | number | undefined) =>
  val == null || val == '' ? '-' : `${val}`

// jika value terisi -> Ya ✔ ; jika kosong/- -> Tidak ✔
const _isFilled = (...vals: (string | number | undefined)[]) =>
  vals.some(
    (v) => v != null && v !== '' && `${v}`.trim() !== '' && `${v}` !== '-',
  )

const ReportPersiapanOperasi = ({
  noreg = '',
  noRm = '',
  isReport = false,
}: ReportPersiapanOperasiProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.persiapanOperasi, noreg],
    queryFn: () => getReportPersiapanOperasi({ noreg: noreg!, no_rm: noRm! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null
  const d = res != null ? res.data : init

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (d == null || d.id === 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 17a' rev='02.2020'>
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={res?.pasien.nama ?? pasien?.nama_pasien ?? ''}
          tanggalLahir={formatDate(res?.pasien.tgl_lahir ?? '') ?? ''}
          noRm={noRm ?? ''}
          nik={res?.pasien.nik ?? ''}
        >
          <h3 className='text-xs font-bold text-center'>
            PERSIAPAN PASIEN SEBELUM OPERASI
          </h3>
        </HeaderFormulir>

        {/* Tabel 4 kolom: Item | Ya | Tidak | Keterangan */}
        <table className='w-full border border-black border-collapse'>
          <thead>
            <tr className='bg-gray-100'>
              <th className='border border-black px-1 text-left'>Item</th>
              <th className='border border-black px-1'>Ya</th>
              <th className='border border-black px-1'>Tidak</th>
              <th className='border border-black px-1 text-left'>Keterangan</th>
            </tr>
          </thead>
          <tbody>
            <SectionRow title='A. Pre Operasi' />
            <Row
              item='1. Tanggal operasi'
              ya={_isFilled(d.tanggal_operasi) ? '✔' : ''}
              tidak={!_isFilled(d.tanggal_operasi) ? '✔' : ''}
              value={formatDate(d.tanggal_operasi)}
            />
            <Row
              item='2. Rencana operasi pukul'
              ya={_isFilled(d.rencana_operasi_pukul) ? '✔' : ''}
              tidak={!_isFilled(d.rencana_operasi_pukul) ? '✔' : ''}
              value={d.rencana_operasi_pukul}
            />
            <Row
              item='3. Dokter ahli bedah'
              ya={_isFilled(d.nama_dokter, d.dokter_ahli_bedah) ? '✔' : ''}
              tidak={!_isFilled(d.nama_dokter, d.dokter_ahli_bedah) ? '✔' : ''}
              value={d.nama_dokter != '' ? d.nama_dokter : d.dokter_ahli_bedah}
            />
            <Row
              item='4. Diagnosa pra bedah'
              ya={_isFilled(d.diagnosa_pra_bedah) ? '✔' : ''}
              tidak={!_isFilled(d.diagnosa_pra_bedah) ? '✔' : ''}
              value={d.diagnosa_pra_bedah}
            />
            <Row
              item='5. Rencana tindakan'
              ya={_isFilled(d.rencana_tindakan) ? '✔' : ''}
              tidak={!_isFilled(d.rencana_tindakan) ? '✔' : ''}
              value={d.rencana_tindakan}
            />
            <Row
              item='6. Dokter anastesi/penata'
              ya={
                _isFilled(d.nama_dokter_anastesi, d.dokter_anastesi) ? '✔' : ''
              }
              tidak={
                !_isFilled(d.nama_dokter_anastesi, d.dokter_anastesi)
                  ? '✔'
                  : ''
              }
              value={
                d.nama_dokter_anastesi != ''
                  ? d.nama_dokter_anastesi
                  : d.dokter_anastesi
              }
            />
            <Row
              item='7. Visite pra anestesi'
              ya={_isFilled(d.visite_pra_anastesi) ? '✔' : ''}
              tidak={!_isFilled(d.visite_pra_anastesi) ? '✔' : ''}
              value={d.visite_pra_anastesi}
            />
            <Row
              item='8. Jenis narkose'
              ya={_isFilled(d.jenis_narcose) ? '✔' : ''}
              tidak={!_isFilled(d.jenis_narcose) ? '✔' : ''}
              value={d.jenis_narcose}
            />
            <Row
              item='9. Visit pra bedah'
              ya={_isFilled(d.visite_pra_bedah) ? '✔' : ''}
              tidak={!_isFilled(d.visite_pra_bedah) ? '✔' : ''}
              value={d.visite_pra_bedah}
            />

            <SectionRow title='B. Persiapan Pasien' />
            <Row
              item='1. Observasi tanda vital'
              ya={
                d.suhu > 0 || d.nadi != '' || d.rr != '' || d.td != ''
                  ? '✔'
                  : ''
              }
              tidak={
                d.suhu <= 0 && d.nadi == '' && d.rr == '' && d.td == ''
                  ? '✔'
                  : ''
              }
              value={`Suhu: ${_v(d.suhu)}  Nadi: ${_v(d.nadi)}  Resp: ${_v(
                d.rr,
              )}  TD: ${_v(d.td)}`}
            />
            <Row
              item='2. Pengukuran'
              ya={d.bb != '' || d.tb != '' ? '✔' : ''}
              tidak={d.bb == '' && d.tb == '' ? '✔' : ''}
              value={`BB: ${_v(d.bb)} kg  TB: ${_v(d.tb)} cm`}
            />
            <Row
              item='3. Riwayat alergi obat-obatan'
              ya={_isFilled(d.riwayat_alergi_obat) ? '✔' : ''}
              tidak={!_isFilled(d.riwayat_alergi_obat) ? '✔' : ''}
              value={d.riwayat_alergi_obat}
            />
            <Row
              item='4. Riwayat penyakit lain'
              ya={_isFilled(d.riwayat_penyakit_lain) ? '✔' : ''}
              tidak={!_isFilled(d.riwayat_penyakit_lain) ? '✔' : ''}
              value={d.riwayat_penyakit_lain}
            />
            <Row
              item='5. Alat kesehatan terpasang'
              ya={_isFilled(d.alkes_terpasang) ? '✔' : ''}
              tidak={!_isFilled(d.alkes_terpasang) ? '✔' : ''}
              value={d.alkes_terpasang}
            />
            <Row
              item='6. Penandaan lokasi operasi'
              ya={d.penandaan_lokasi_operasi != '' ? '✔' : ''}
              tidak={d.penandaan_lokasi_operasi == '' ? '✔' : ''}
              value={d.penandaan_lokasi_operasi}
            />
            <Row
              item='7. Dicukur atau tidak'
              ya={d.dicukur_tanggal != '' || d.dicukur_oleh != '' ? '✔' : ''}
              tidak={
                d.dicukur_tanggal == '' && d.dicukur_oleh == '' ? '✔' : ''
              }
              value={`Tgl & jam: ${_v(formatDate(d.dicukur_tanggal))}  Oleh: ${_v(
                d.dicukur_oleh,
              )}`}
            />
            <Row
              item='8. Persiapan transfusi / tidak'
              ya={d.persiapan_transfusi != '' ? '✔' : ''}
              tidak={d.persiapan_transfusi == '' ? '✔' : ''}
              value={d.persiapan_transfusi}
            />
            <Row
              item='9. Puasa'
              ya={d.puasa != '' ? '✔' : ''}
              tidak={d.puasa == '' ? '✔' : ''}
              value={d.puasa}
            />
            <Row
              item='10. Diberikan premedikasi'
              ya={d.diberikan_premedikasi != '' ? '✔' : ''}
              tidak={d.diberikan_premedikasi == '' ? '✔' : ''}
              value={d.diberikan_premedikasi}
            />
            <Row
              item='11. Protease dilepas'
              ya={d.protease_dilepas != '' ? '✔' : ''}
              tidak={d.protease_dilepas == '' ? '✔' : ''}
              value={`Disimpan oleh: ${_v(d.protease_dilepas)}`}
            />
            <Row
              item='12. Perhiasan pasien dilepas'
              ya={d.perhiasan_pasien_dilepas != '' ? '✔' : ''}
              tidak={d.perhiasan_pasien_dilepas == '' ? '✔' : ''}
              value={`Disimpan oleh: ${_v(d.perhiasan_pasien_dilepas)}`}
            />
            <Row
              item='13. Dilakukan pengosongan kandung kemih'
              ya={d.pengosongan_kandung_kemih != '' ? '✔' : ''}
              tidak={d.pengosongan_kandung_kemih == '' ? '✔' : ''}
              value={d.pengosongan_kandung_kemih}
            />

            <SectionRow title='C. Persiapan Administrasi Pasien' />
            <Row
              item='1. Pengkajian pra anestesi'
              ya={_isFilled(d.lembar_visite_pra_anestesi) ? '✔' : ''}
              tidak={!_isFilled(d.lembar_visite_pra_anestesi) ? '✔' : ''}
              value={d.lembar_visite_pra_anestesi}
            />
            <Row
              item='2. Surat ijin operasi'
              ya={_isFilled(d.surat_ijin_operasi) ? '✔' : ''}
              tidak={!_isFilled(d.surat_ijin_operasi) ? '✔' : ''}
              value={d.surat_ijin_operasi}
            />
            <Row
              item='3. Surat ijin anestesi'
              ya={_isFilled(d.surat_ijin_anastesi) ? '✔' : ''}
              tidak={!_isFilled(d.surat_ijin_anastesi) ? '✔' : ''}
              value={d.surat_ijin_anastesi}
            />
            <Row
              item='4. Berkas rekam medis'
              ya={_isFilled(d.berkas_rm) ? '✔' : ''}
              tidak={!_isFilled(d.berkas_rm) ? '✔' : ''}
              value={d.berkas_rm}
            />
            <Row
              item='5. Rontgen'
              ya={_isFilled(d.rontgen) ? '✔' : ''}
              tidak={!_isFilled(d.rontgen) ? '✔' : ''}
              value={d.rontgen}
            />
            <Row
              item='6. USG'
              ya={_isFilled(d.usg) ? '✔' : ''}
              tidak={!_isFilled(d.usg) ? '✔' : ''}
              value={d.usg}
            />
            <Row
              item='7. EKG'
              ya={_isFilled(d.ekg) ? '✔' : ''}
              tidak={!_isFilled(d.ekg) ? '✔' : ''}
              value={d.ekg}
            />
            <Row
              item='8. Laboratorium'
              ya={_isFilled(d.laboratorium) ? '✔' : ''}
              tidak={!_isFilled(d.laboratorium) ? '✔' : ''}
              value={d.laboratorium}
            />
            <Row
              item='9. Lain-lain (mandi, clisma)'
              ya={_isFilled(d.lain_lain) ? '✔' : ''}
              tidak={!_isFilled(d.lain_lain) ? '✔' : ''}
              value={d.lain_lain}
            />
          </tbody>
        </table>

        {/* Signature */}
        <div className='flex justify-between items-start mt-10'>
          <div className='text-center'>
            <p className='text-xs font-semibold'>
              Perawat Ruangan, {formatDate(d.insert_dttm)}
            </p>
            <div className='h-[10px]' />
            {d.nama_perawat != '' ? (
              <QRCode
                value={d.nama_perawat}
                className='h-[50px] w-[50px] mx-auto'
              />
            ) : (
              <div className='h-[50px]' />
            )}
            <p className='text-xs mt-5'>
              {d.nama_perawat || '( ................................. )'}
            </p>
          </div>
          <div className='text-center'>
            <p className='text-xs font-semibold'>Perawat Kamar Bedah</p>
            <div className='h-[10px]' />
            {d.nama_perawat_ok != '' ? (
              <QRCode
                value={d.nama_perawat_ok}
                className='h-[50px] w-[50px] mx-auto'
              />
            ) : (
              <div className='h-[50px]' />
            )}
            <p className='text-xs mt-10'>
              {d.nama_perawat_ok || '( ................................. )'}
            </p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}

const SectionRow = ({ title }: { title: string }) => (
  <tr className='bg-gray-100'>
    <td colSpan={4} className='border border-black px-1 font-semibold'>
      {title}
    </td>
  </tr>
)

const Row = ({
  item,
  ya = '',
  tidak = '',
  value = '',
}: {
  item: string
  ya?: string
  tidak?: string
  value?: string
}) => (
  <tr>
    <td className='border border-black px-1'>{item}</td>
    <td className='border border-black px-1 text-center'>{ya}</td>
    <td className='border border-black px-1 text-center'>{tidak}</td>
    <td className='border border-black px-1'>{value}</td>
  </tr>
)

export default ReportPersiapanOperasi
