import type {
  PemasanganFoleyCatheter,
  PemasanganIvp,
  PemasanganNgt,
} from '@/models/pemasangan-pemantauan'
import { PemantauanGDSResponse } from '@/models/pemantauan-gds'
import type { PemantauanLukaOperasiResponse } from '@/models/pemantauan-luka-operasi'
import type { Response } from '@/type'

import { post } from './api-2'

const getPemantauanGds = async ({
  kd_bagian,
  no_reg,
  no_rm,
}: {
  no_reg: string
  kd_bagian: string
  no_rm: string
}): Promise<Response<PemantauanGDSResponse>> => {
  const response = await post(`/v1/pemasangan-pemantauan/gds/report`, {
    kd_bagian,
    no_reg,
    no_rm,
  })

  return response.data
}

