import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { getEarlyWarningSystem } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime, formatDateTimev2 } from '@/utils/formatDate'

import { TextTitle } from './text-title'

/* Legenda risiko — mirror Flutter report_dewasa_widget.dart & dto.KeteranganEWS backend */
const resikoRingan =
  'RISIKO RINGAN\n⚫Asemen Perawatan Senior\n⚫Monitoring per 4-6 jam'
const resikoSedang =
  'RISIKO SEDANG\n⚫Panggil bantuan PPJA dan dokter jaga\n⚫ Monitoring setiap 2 jam atau lebih cepat\n⚫ Konsultasi ke dokter DPJP dan spesialis terkait\n⚫ Jika diperlukan, dipindahkan ke ICU'
const resikoTinggi =
  'RISIKO TINGGI\n⚫Panggil bantuan perawat senior dan dokter jaga bangsal\n⚫Lakukan resusitasi, buka jalan nafas, support pentilasi, oksigenisasi dan sirkulasi\n⚫Siapkan peralatan dan obat-obatan emergency monitoring secara continue\n⚫Konsultasi ke dokter DPJP, komunikasi ke keluarga pasien'
const hentiNafas =
  'Henti Hafas - Henti Jantung\n⚫Lakukan resusitasi, buka jalan nafas, support pentilasi, okigenisasi dari sirkulasi,\n⚫Aktivitas kode blue '

type KontrolPasienProps = {
  noreg: string
  kdBagian: string
  isReport?: boolean
}

const KontrolPasien = ({ noreg, kdBagian, isReport }: KontrolPasienProps) => {
  const { pasien } = usePasienStore((state) => state)

  const kd = kdBagian || pasien?.kd_bagian || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.ews, noreg],
    queryFn: () => getEarlyWarningSystem(noreg, kd),
    enabled: !!noreg,
  })

  const res =
    data != null ? data.response.filter((i) => i.Kategori === 'DEWASA') : []
  console.log('res ews', res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 3' rev='02.2026'>
      <div className='p-2 text-xs'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={pasien?.tgl_lahir ?? ''}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3>PEMANTAUAN TANDA VITAL / NEWS2</h3>
        </HeaderFormulir>

        <div className='flex items-center justify-between'>
          <TextTitle
            title={`Tanggal : ${formatDateTime(res[0].InsertDttm) ?? ''}`}
          />
        </div>

        {/* Tabel Skor NEWS2 */}
        <TextTitle title='Data Pemantauan NEWS2' />
        <table className='w-full border border-black border-collapse mb-2'>
          <thead>
            <tr className='bg-gray-100'>
              <th className='border border-black px-1'>Waktu</th>
              <th className='border border-black px-1'>Pernapasan</th>
              <th className='border border-black px-1'>SpO2</th>
              <th className='border border-black px-1'>TD Sistolik</th>
              <th className='border border-black px-1'>Nadi</th>
              <th className='border border-black px-1'>Kesadaran</th>
              <th className='border border-black px-1'>Suhu</th>
              <th className='border border-black px-1'>Total Skor</th>
              <th className='border border-black px-1'>Monitoring</th>
              <th className='border border-black px-1'>Eskalasi</th>
              <th className='border border-black px-1'>Ket.</th>
            </tr>
          </thead>
          <tbody>
            {res.map((item, i) => (
              <tr key={i}>
                <td className='border border-black px-1'>
                  {formatDateTimev2(item.InsertDttm)}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.Pernapasan}
                  <span className='text-[10px]'>
                    {' '}
                    {/* ({item.TotalPernapasan ?? '-'}) */}
                  </span>
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.Spo2}
                  <span className='text-[10px]'>
                    {' '}
                    {/* ({item.TotalSPO2 ?? '-'}) */}
                  </span>
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.TDSistolik}
                  <span className='text-[10px]'>
                    {' '}
                    {/* ({item.TotalSistolik ?? '-'}) */}
                  </span>
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.Nadi}
                  <span className='text-[10px]'>
                    {' '}
                    {/* ({item.TotalNadi ?? '-'}) */}
                  </span>
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.Kesadaran}
                  <span className='text-[10px]'>
                    {' '}
                    {/* ({item.TotalKesadaran ?? '-'}) */}
                  </span>
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.Suhu}
                  {/* <span className='text-[10px]'> ({item.SkorSuhu ?? '-'})</span> */}
                </td>
                <td className='border border-black px-1 text-center font-semibold'>
                  {/* {item.Total ?? item.SkorEWS ?? '-'} */}
                </td>
                <td className='border border-black px-1'>
                  {/* {item.Monitoring ?? '-'} */}
                </td>
                <td className='border border-black px-1'>
                  {/* {item.Eskalasi ?? '-'} */}
                </td>
                <td className='border border-black px-1'>
                  {toKeteranganEWSNews(item.Total ?? 0) ?? '-'}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {/* Tabel Skor NEWS2 */}

        <TextTitle title='Keterangan' />
        <ul>
          <li>Ringan: {resikoRingan}</li>
          <li>Sedang: {resikoSedang}</li>
          <li>Tinggi: {resikoTinggi}</li>
          <li>Henti Nafas: {hentiNafas}</li>
        </ul>
      </div>
    </LayoutBorderNo>
  )
}

export default KontrolPasien

function toKeteranganEWSNews(value: number): string {
  if (value >= 0 && value <= 4) {
    return 'RISIKO RINGAN'
  } else if (value == 5 || value == 6) {
    return 'RISIKO SEDANG'
  } else if (value == 7) {
    return 'RISIKO TINGGI'
  } else if (value >= 8) {
    return 'HENTI NAFAS'
  }

  return ''
}
