import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { PemantauanLukaOperasiModel } from '@/models/pemantauan-luka-operasi'
import { getPemantauanLukaOperasi } from '@/services/pemasangan-pemantauan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportPemantauanLukaOperasiProps {
  isReport?: boolean
  noreg?: string
  noRm?: string
  kdBagian?: string
}

const init: PemantauanLukaOperasiModel = {
  id: 0,
  insert_dttm: '',
  noreg: '',
  kd_bagian: '',
  pelayanan: '',
  insert_user_id: '',
  tanggal_operasi: '',
  daerah_operasi: '',
  dokter: '',
  pemberian_antibiotika: '',
  perawat: '',
}

const _v = (val: string | undefined) =>
  val == null || val.trim() == '' ? '-' : val.trim()

const ReportPemantauanLukaOperasi = ({
  noreg = '',
  noRm = '',
  kdBagian = '',
  isReport = false,
}: ReportPemantauanLukaOperasiProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pemantauanLukaOperasi, noreg],
    queryFn: () =>
      getPemantauanLukaOperasi({
        kd_bagian: kdBagian,
        no_reg: noreg!,
        no_rm: noRm,
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null
  const d = res != null ? res.data : init
  const detail = res?.detail ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (d == null || d.id === 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 17o' rev='02.2020'>
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={res?.pasien.nama ?? pasien?.nama_pasien ?? ''}
          tanggalLahir={formatDate(res?.pasien.tgl_lahir ?? '') ?? ''}
          noRm={noRm ?? ''}
          nik={res?.pasien.nik ?? ''}
        >
          <h3 className='text-xs font-bold text-center'>
            PEMANTAUAN LUKA OPERASI
          </h3>
        </HeaderFormulir>

        {/* Header info */}
        <div className='my-2'>
          <Field label='1. Tanggal operasi : ' value={_v(d.tanggal_operasi)} />
          <Field
            label='2. Daerah yang dioperasi : '
            value={_v(d.daerah_operasi)}
          />
          <Field
            label='3. Dokter yang melakukan operasi : '
            value={_v(d.dokter)}
          />
          <Field
            label='4. Pemberian antibiotika : '
            value={_v(d.pemberian_antibiotika)}
          />
        </div>

        {/* Tabel detail */}
        <table className='w-full border border-black border-collapse'>
          <thead>
            <tr className='bg-gray-100'>
              <th className='border border-black px-1'>Tanggal</th>
              <th className='border border-black px-1'>Hari ke</th>
              <th className='border border-black px-1'>Keadaan Luka</th>
              <th className='border border-black px-1'>Ganti Balutan</th>
              <th className='border border-black px-1'>Nosokomial</th>
              <th className='border border-black px-1'>Petugas</th>
              <th className='border border-black px-1'>Keterangan</th>
            </tr>
          </thead>
          <tbody>
            {detail.map((item, i) => (
              <tr key={i}>
                <td className='border border-black px-1 text-center'>
                  {item.tanggal}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.hari_ke}
                </td>
                <td className='border border-black px-1'>
                  {item.keadaan_luka}
                </td>
                <td className='border border-black px-1'>
                  {item.ganti_balutan}
                </td>
                <td className='border border-black px-1'>{item.nosokomial}</td>
                <td className='border border-black px-1 text-center'>
                  {item.perawat != '' ? (
                    <QRCode
                      value={item.perawat}
                      className='h-[50px] w-[50px] inline-block align-middle'
                    />
                  ) : null}
                  <div className='text-xs'>{item.perawat}</div>
                </td>
                <td className='border border-black px-1'>{item.keterangan}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </LayoutBorderNo>
  )
}

const Field = ({ label, value }: { label: string; value: string }) => (
  <p className='text-xs my-0.5'>
    <span className='font-bold'>{label}</span>
    {value}
  </p>
)

export default ReportPemantauanLukaOperasi
