import { ReportPenyakitMenular } from '@/models/penyakit-menular'
import type { Response } from '@/type'

import { post } from './api-2'

const getReportPenyakitMenular = async ({
  noreg,
  kd_bagian,
}: {
  noreg: string
  kd_bagian: string
}): Promise<Response<ReportPenyakitMenular>> => {
  const response = await post(`/v1/penyakit-menular/report`, {
    noreg: noreg,
    kd_bagian: kd_bagian,
  })

  return response.data
}

export { getReportPenyakitMenular }
