import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function toTarget(kategori: string, angka: number | string) {
  const value = Number(angka)
  switch (kategori) {
    case 'Meningkat':
      return ['', 'Meningkat', 'Cukup Meningkat', 'Sedang', 'Cukup Menurun', 'Menurun'][value] ?? ''
    case 'Memburuk':
      return ['', 'Memburuk', 'Cukup Memburuk', 'Sedang', 'Cukup Membaik', 'Membaik'][value] ?? ''
    default:
      return ['', 'Menurun', 'Cukup Menurun', 'Sedang', 'Cukup Meningkat', 'Meningkat'][value] ?? ''
  }
}
