import React from 'react'

import { Radiologi } from '@/type'
import { formatDate } from '@/utils/formatDate'

export function PemeriksaanRadiologi({ data }: { data: Radiologi[] }) {
  const group: Record<string, Radiologi[]> = {}

  for (let i = 0; i < data.length; i++) {
    const curr = data[i]
    const tanggal = formatDate(curr.tanggal)

    if (!group[tanggal]) {
      group[tanggal] = []
    }
    group[tanggal].push(curr)
  }

  const list = Object.keys(group).map((k) => {
    return group[k]
  })

  console.log('list', list)

  // check honor
  // const re = /Honor/i

  if (list.length > 0) {
    return (
      <div className='border border-black'>
        {list.map((k, idx) => (
          <div key={idx}>
            <div className='p-1 bg-gray-300'>
              <p className='text-xs'>{formatDate(k[0].tanggal)}</p>
            </div>
            {k.map((item, index) => (
              <div key={`radiologi-kelompok-${index}`} className='bg-gray-400'>
                <p className='p-2 text-xs font-bold'>
                  {item.radiologi
                    // .filter((i) => !re.test(i.pemeriksaan_deskripsi))
                    .map((i) => i.pemeriksaan_deskripsi)
                    .join(', ')}
                </p>
                <div key={index + 7}>
                  {item.radiologi.map((item, index) => (
                    <React.Fragment key={`item-radiologi-${index}`}>
                      <div>
                        <div className='border-t border-b border-black'>
                          <h3 className='text-center font-bold py-2 text-xs'>
                            Pemeriksaan :{' '}
                          </h3>
                        </div>
                        <div className='border-b bg-white'>
                          {/* {re.test(item.pemeriksaan_deskripsi) ? (
                            <p className='p-2 text-xs'>-</p>
                          ) : (
                            <p className='p-2 text-xs'>
                              {item.pemeriksaan_deskripsi}
                            </p>
                          )} */}
                          <p className='p-2 text-xs'>
                            {item.pemeriksaan_deskripsi}
                          </p>
                        </div>
                      </div>
                      <div>
                        <div className='border-t border-b border-black'>
                          <h3 className='text-center font-bold py-2 text-xs'>
                            Uraian :{' '}
                          </h3>
                        </div>
                        <div className='border-b bg-white'>
                          <p className='p-2 text-xs'>{item.uraian}</p>
                        </div>
                      </div>
                      <div>
                        <div className='border-t border-b border-black'>
                          <h3 className='text-center font-bold py-2 text-xs'>
                            Hasil :{' '}
                          </h3>
                        </div>
                        <div className='border-b bg-white'>
                          <p className='p-2 text-xs'>{item.hasil}</p>
                        </div>
                      </div>
                    </React.Fragment>
                  ))}
                </div>
              </div>
            ))}
          </div>
        ))}
      </div>
    )
  } else {
    return (
      <p className='text-xs font-medium text-center'>
        Tidak ada pemeriksaan radiologi
      </p>
    )
  }
}
