import { cn } from '@/lib/utils'
import type { PengkajianKulit } from '@/models/asesmen-geriatri'

type PengkajianKulitProps = {
  data: PengkajianKulit
}

const PengkajianKulit = ({ data }: PengkajianKulitProps) => {
  return (
    <div className='mb-2'>
      <p className='flex-1 font-semibold'>PENGKAJIAN KULIT</p>
      <p className='text-xs'>Warna Kulit : {data.warna_kulit}</p>
      <p className='text-xs'>Skor Braden : {data.skor_braden}</p>
      <p className='text-xs'>Terdapat Luka : {data.terdapat_luka} </p>
      <div className='flex'>
        <div className='flex-1 border border-black border-r-0 border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>
            PARAMETER
          </p>
        </div>
        <div className='flex-[0.5] border border-black border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>SKOR</p>
        </div>
      </div>
      <Item
        k={`PERSEPSI SENSORI : Kemampuan untuk merespons ketidaknyamanan tekanan `}
        v={`${toSkorPersespsiSensori(data.skor_persepsi_sensori)}`}
      />
      <Item
        k={`KELEMBAPAN : sejauh mana kulit terpapar kelembapan  `}
        v={`${toSkorKelembapan(data.skor_kelembapan)}`}
      />
      <Item
        k={`AKTIVITAS : tingkat aktivitas fisik  `}
        v={`${toSkorAktivitas(data.skor_aktivitas)}`}
      />
      <Item
        k={`MOBILITAS : kemampuan tubuh untuk mengubah dan mengontrol posisi tubuh  `}
        v={`${toSkorMobilitas(data.skor_mobilitas)}`}
      />
      <Item
        k={`NUTRISI : Pola asupan makanan  `}
        v={`${toSkorNutrisi(data.skor_nutrisi)}`}
      />
      <Item
        k={`FRIKSI DAN GESEKAN`}
        v={`${toSkorFriksiDanGesekan(data.skor_friksi_dan_gesekan)}`}
      />

      <Item isLast k='Total Skor' v={`${data.total}`} />
    </div>
  )
}

export default PengkajianKulit

const Item = ({ k, v, isLast }: { k: string; v: string; isLast?: boolean }) => {
  return (
    <div className='flex'>
      <div
        className={cn(
          'flex-1 border border-black border-r-0  p-2 border-b-[0] ',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{k}</p>
      </div>
      <div
        className={cn(
          'flex-[0.5] border border-black p-2 border-b-[0]',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{v}</p>
      </div>
    </div>
  )
}

function toSkorPersespsiSensori(skor: number) {
  switch (skor) {
    case 1:
      return 'Tidak berespon (1)'
    case 2:
      return 'Sangat terbatas (2)'
    case 3:
      return 'Sedikit terbatas (3)'
    case 4:
      return 'Tidak ada gangguan (4)'
    default:
      return ''
  }
}

function toSkorKelembapan(skor: number) {
  switch (skor) {
    case 1:
      return 'Kelembaban konstan (1)'
    case 2:
      return 'Sering lembab (2)'
    case 3:
      return 'Kadang lembab (3)'
    case 4:
      return 'Jarang lembab (4)'
    default:
      return ''
  }
}

function toSkorAktivitas(skor: number) {
  switch (skor) {
    case 1:
      return 'Tergeletak di tempat tidur (1)'
    case 2:
      return 'Tidak bisa berjalan (2)'
    case 3:
      return 'Berjalan pada jarak terbatas (3)'
    case 4:
      return 'Berjalan di sekitar ruangan (4)'
    default:
      return ''
  }
}

function toSkorMobilitas(skor: number) {
  switch (skor) {
    case 1:
      return 'Tidak bisa bergerak (1)'
    case 2:
      return 'Sangat terbatas (2)'
    case 3:
      return 'Sedikit terbatas (3)'
    case 4:
      return 'Tidak ada batasan (4)'
    default:
      return ''
  }
}

function toSkorNutrisi(skor: number) {
  switch (skor) {
    case 1:
      return 'Sangat buruk (1)'
    case 2:
      return 'Kurang adekuat (2)'
    case 3:
      return 'Adekuat (3)'
    case 4:
      return 'Sangat baik (4)'
    default:
      return ''
  }
}

function toSkorFriksiDanGesekan(skor: number) {
  switch (skor) {
    case 1:
      return 'Masalah (1)'
    case 2:
      return 'Potensi Masalah (2)'
    case 3:
      return 'Sangat Baik (3)'
    default:
      return ''
  }
}
