import { Loader2, PlusSquareIcon } from 'lucide-react'

import { useEffect, useState } from 'react'

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { createFileRoute } from '@tanstack/react-router'

import Error from '@/components/error'
import Loading from '@/components/loading'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { SkriningPasienLuarForm } from '@/features/skrining-pasien-luar/components/skrining-pasien-luar-form'
import { SkriningPasienLuarDetail } from '@/features/skrining-pasien-luar/components/skrining-pasien-luar-report'
import { columns } from '@/features/skrining-pasien-luar/components/table/columns'
import { DataTable } from '@/features/triase/components/table/data-table'
import { SkriningPasienLuar } from '@/models/skrining-pasien-luar'
import {
  deleteSkriningPasienLuar,
  searchSkriningPasienLuar,
} from '@/services/skrining-pasien-luar'
import { useGlobalStore } from '@/store/global.store'
import { MetaPaginated } from '@/type'
import { constants } from '@/utils/constants'

const LIMIT = 10

export const Route = createFileRoute('/skrining-pasien-luar/')({
  component: SkriningPasienLuarPage,
})

export default function SkriningPasienLuarPage() {
  const isLogin = JSON.parse(sessionStorage.getItem('isLogin')!)

  if (!isLogin) {
    // if not logged in, navigate to login page
    window.location.replace('/login')
  }

  const { dialogId, setDialogId, showDialog, setShowDialog, item } =
    useGlobalStore((s) => s)

  const queryClient = useQueryClient()

  const [search, setSearch] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  const [page, setPage] = useState(1)

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search)
      setPage(1)
    }, 400)
    return () => clearTimeout(timer)
  }, [search])

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.skriningPasienLuar.list,
      page,
      debouncedSearch,
    ],
    queryFn: () =>
      searchSkriningPasienLuar({ page, limit: LIMIT, search: debouncedSearch }),
  })

  const { mutateAsync: mutateDelete, isPending: isDeleting } = useMutation({
    mutationFn: deleteSkriningPasienLuar,
  })

  const result = data?.response ?? []
  const meta = data?.metadata as MetaPaginated | undefined
  const totalPage = meta?.total_page ?? 1
  const selectedItem = item as SkriningPasienLuar | null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <>
      <div className='flex'>
        <main className='h-[calc(100vh-5rem)] overflow-y-scroll w-full p-4 bg-gradient-to-b from-blue-500  to-[#0066CB] mt-2 mx-2 rounded-md'>
          <div className='mb-3 flex items-center justify-between'>
            <Input
              placeholder='Cari nama pasien / diagnosa...'
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className='max-w-sm bg-white text-black'
            />
            <Button
              onClick={() => {
                setDialogId('dialog-add-skrining-pasien-luar')
                setShowDialog(true)
              }}
              className='bg-white text-blue-500 hover:bg-gray-100 hover:text-blue-700'
            >
              Tambah <PlusSquareIcon />
            </Button>
          </div>
          <DataTable columns={columns} data={result} />
          <div className='flex items-center justify-between mt-3'>
            <p className='text-white text-sm'>
              Halaman {page} dari {totalPage}
            </p>
            <div className='flex gap-2'>
              <Button
                variant='outline'
                size='sm'
                disabled={page <= 1}
                onClick={() => setPage((p) => p - 1)}
                className='text-black'
              >
                &laquo; Sebelumnya
              </Button>
              <Button
                variant='outline'
                size='sm'
                disabled={page >= totalPage}
                onClick={() => setPage((p) => p + 1)}
                className='text-black'
              >
                Selanjutnya &raquo;
              </Button>
            </div>
          </div>
        </main>
      </div>

      <Dialog
        modal
        open={showDialog && dialogId == 'dialog-add-skrining-pasien-luar'}
        onOpenChange={() => {
          setShowDialog(!showDialog)
        }}
      >
        <DialogTitle className='sr-only'>
          Tambah Skrining Pasien Luar
        </DialogTitle>
        <DialogDescription className='sr-only'>
          Form tambah data skrining pasien luar
        </DialogDescription>
        <DialogContent className='max-w-2xl sm:max-h-[90vh] overflow-y-auto'>
          <h2 className='text-xl font-semibold text-blue-600 pt-2'>
            Tambah Skrining Pasien Luar
          </h2>
          <SkriningPasienLuarForm />
        </DialogContent>
      </Dialog>

      <Dialog
        modal
        open={dialogId == 'dialog-detail-skrining-pasien-luar'}
        onOpenChange={() => setDialogId('')}
      >
        <DialogTitle className='sr-only'>
          Detail Skrining Pasien Luar
        </DialogTitle>
        <DialogDescription className='sr-only'>
          Detail data skrining pasien luar
        </DialogDescription>
        <DialogContent className='max-w-2xl max-h-[90vh] overflow-y-auto'>
          <h2 className='text-xl font-semibold text-blue-600 pt-2'>
            Detail Skrining — {selectedItem?.data.nama ?? ''}
          </h2>
          {selectedItem != null && (
            <SkriningPasienLuarDetail item={selectedItem} />
          )}
        </DialogContent>
      </Dialog>

      <Dialog
        modal
        open={showDialog && dialogId == 'dialog-edit-skrining-pasien-luar'}
        onOpenChange={() => {
          setShowDialog(!showDialog)
        }}
      >
        <DialogTitle className='sr-only'>Edit Skrining Pasien Luar</DialogTitle>
        <DialogDescription className='sr-only'>
          Form edit data skrining pasien luar
        </DialogDescription>
        <DialogContent className='max-w-2xl sm:max-h-[90vh] overflow-y-auto'>
          <h2 className='text-xl font-semibold text-blue-600 pt-2'>
            Edit Skrining Pasien Luar
          </h2>
          {selectedItem != null && (
            <SkriningPasienLuarForm
              editId={selectedItem.id}
              initialData={{
                id: selectedItem.id,
                ...selectedItem.data,
              }}
            />
          )}
        </DialogContent>
      </Dialog>

      <AlertDialog open={dialogId == 'dialog-delete-skrining-pasien-luar'}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus data skrining?</AlertDialogTitle>
            <AlertDialogDescription>
              Tindakan ini tidak dapat dibatalkan. Data skrining dari petugas{' '}
              <span className='font-semibold'>
                {selectedItem?.data.petugas ?? ''}
              </span>{' '}
              akan dihapus secara permanen.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              disabled={isDeleting}
              onClick={() => {
                setDialogId('')
              }}
            >
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              className='bg-red-500 hover:bg-red-600'
              disabled={isDeleting}
              onClick={async () => {
                if (!selectedItem) return
                await mutateDelete({ id: selectedItem.id })
                await queryClient.invalidateQueries({
                  queryKey: [constants.queryKey.skriningPasienLuar.list],
                })
                setDialogId('')
              }}
            >
              {isDeleting ? (
                <>
                  <Loader2 className='mr-2 h-4 w-4 animate-spin' />
                  Menghapus...
                </>
              ) : (
                'Hapus'
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}
