import { createFileRoute } from '@tanstack/react-router'

import { Button } from '@/components/ui/button'
import { fixVerifDiagnosa } from '@/services/rekam-medis'

export const Route = createFileRoute('/_diagnosa')({
  component: Render,
})

function Render() {
  async function onClick() {
    try {
      const res = await fixVerifDiagnosa()
      console.log('res', res)
      alert('success update data')
    } catch (error) {
      console.log('error while fix verif diagnosa', error)
    }
  }

  return (
    <div className="min-h-screen max-width flex items-center justify-center">
      <Button onClick={onClick}>UPDATE DIAGNOSA</Button>
    </div>
  )
}
