import { z } from 'zod'

import { useForm } from 'react-hook-form'

import { zodResolver } from '@hookform/resolvers/zod'
import { useMutation, useQueryClient } from '@tanstack/react-query'

import {
  createSkriningPasienLuar,
  updateSkriningPasienLuar,
} from '@/services/skrining-pasien-luar'
import { useGlobalStore } from '@/store/global.store'
import { constants } from '@/utils/constants'

const skriningPasienLuarSchema = z.object({
  petugas: z.string().min(1, 'Wajib diisi'),
  identitas_pengirim: z.string().min(1, 'Wajib diisi'),
  hp: z.string().min(1, 'Wajib diisi'),
  rujukan: z.string().min(1, 'Wajib diisi'),
  cara_informasi_datang: z.string().min(1, 'Wajib diisi'),
  diagnosa: z.string().min(1, 'Wajib diisi'),
  keluhan: z.string().min(1, 'Wajib diisi'),
  gcs_e: z.string().min(1, 'Wajib diisi'),
  gcs_m: z.string().min(1, 'Wajib diisi'),
  gcs_v: z.string().min(1, 'Wajib diisi'),
  td: z.string().min(1, 'Wajib diisi'),
  nadi: z.string().min(1, 'Wajib diisi'),
  suhu: z.string().min(1, 'Wajib diisi'),
  pernafasan: z.string().min(1, 'Wajib diisi'),
  spo2: z.string().min(1, 'Wajib diisi'),
  kebutuhan_sarana: z.string().min(1, 'Wajib diisi'),
  rekomendasi: z.string().min(1, 'Wajib diisi'),
  saran: z.string().min(1, 'Wajib diisi'),
  id: z.number().optional(),
  nama: z.string().min(1, 'Wajib diisi'),
  nik: z.string().min(1, 'Wajib diisi'),
  jenis_kelamin: z.string().min(1, 'Wajib diisi'),
  tanggal_lahir: z.string().min(1, 'Wajib diisi'),
  alamat: z.string().min(1, 'Wajib diisi'),
})

export type CreateSkriningPasienLuarReq = z.infer<
  typeof skriningPasienLuarSchema
>

export function useSkriningPasienLuar(
  editId?: number,
  initialData?: CreateSkriningPasienLuarReq,
) {
  const queryClient = useQueryClient()
  const { setDialogId, setShowDialog } = useGlobalStore()

  const defaultValues: CreateSkriningPasienLuarReq = {
    petugas: '',
    identitas_pengirim: '',
    hp: '',
    rujukan: '',
    cara_informasi_datang: '',
    diagnosa: '',
    keluhan: '',
    gcs_e: '',
    gcs_m: '',
    gcs_v: '',
    td: '',
    nadi: '',
    suhu: '',
    pernafasan: '',
    spo2: '',
    kebutuhan_sarana: '',
    rekomendasi: '',
    saran: '',
    id: editId ?? -1,
    nama: '',
    nik: '',
    jenis_kelamin: '',
    tanggal_lahir: '',
    alamat: '',
  }

  const form = useForm<CreateSkriningPasienLuarReq>({
    resolver: zodResolver(skriningPasienLuarSchema),
    defaultValues: initialData || defaultValues,
  })

  const { mutateAsync, isPending } = useMutation({
    mutationFn: editId ? updateSkriningPasienLuar : createSkriningPasienLuar,
  })

  async function onSubmit(values: CreateSkriningPasienLuarReq) {
    if (editId) {
      await mutateAsync({ id: editId, data: values })
    } else {
      await mutateAsync({
        id: (values.id ?? -1) as number,
        data: values,
      })
    }
    await queryClient.invalidateQueries({
      queryKey: [constants.queryKey.skriningPasienLuar.list],
    })
    form.reset()
    setDialogId('')
    setShowDialog(false)
  }

  return { form, onSubmit, isPending, isEditMode: !!editId }
}
