import type {
  DiagnosaKeperawatan,
  DiagnosaKeperawatanDetail,
  SDKISLKIResponse,
} from '@/models/sdki-slki'
import type { Response } from '@/type'

import { get, post } from './api-2'

/**
 * Master seluruh diagnosa keperawatan (SDKI) beserta kode SLKI/SIKI yang dipetakan.
 * Backend: `GET /app/v1/master-diagnosa-keperawatan` — PUBLIK, tanpa JWT,
 * di-cache 24 jam di server (`cachePublic`).
 *
 * Catatan: endpoint lama `GET /app/v1/diagnosa-keperawatan` memakai JWT dan
 * tidak menyertakan kode pemetaan.
 */
const getDaftarDiagnosaKeperawatan = async (): Promise<
  Response<DiagnosaKeperawatan[]>
> => {
  const response = await get('/v1/master-diagnosa-keperawatan')

  return response.data
}

/**
 * Pencarian diagnosa keperawatan beserta kode SLKI/SIKI yang dipetakan.
 * Backend: `GET /app/v1/sdki/:judul` -> `LIKE %judul%` pada `judul` ATAU `kode`.
 * `judul` tidak boleh kosong karena Fiber memakai `StrictRouting`.
 */
const cariDiagnosaKeperawatan = async (
  judul: string,
): Promise<Response<DiagnosaKeperawatanDetail[]>> => {
  const response = await get(`/v1/sdki/${encodeURIComponent(judul)}`)

  return response.data
}

/**
 * Pemetaan lengkap satu diagnosa: SDKI + daftar SLKI (dengan kriteria hasil)
 * + daftar SIKI (dengan deskripsi intervensi).
 * Backend: `POST /app/v1/deskripsi-luaran-slki`, body `{ kode_diagnosa }`.
 *
 * Bila kode tidak ditemukan backend membalas `{ metadata }` tanpa `response`,
 * sehingga pemanggil wajib memeriksa `data.response` sebelum dipakai.
 */
const getMappingDiagnosa = async (
  kodeDiagnosa: string,
): Promise<Response<SDKISLKIResponse>> => {
  const response = await post('/v1/deskripsi-luaran-slki', {
    kode_diagnosa: kodeDiagnosa,
  })

  return response.data
}

export {
  cariDiagnosaKeperawatan,
  getDaftarDiagnosaKeperawatan,
  getMappingDiagnosa,
}
