import { LoaderCircle } from 'lucide-react'

import { createFileRoute } from '@tanstack/react-router'

import { images } from '@/assets/images/images'
import Layout from '@/components/layout'
import { Button } from '@/components/ui/button'
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form'
import { Input } from '@/components/ui/input'
import { useLogin } from '@/hooks/auth/use-login'
import { constants } from '@/utils/constants'

export const Route = createFileRoute('/login')({
  component: Login,
})

function Login() {
  const {
    // authState,
    form,
    onSubmit,
    status,
  } = useLogin()

  const isLogin = JSON.parse(sessionStorage.getItem('isLogin')!)

  if (isLogin) {
    // if user logged in, navigate to dashboard
    window.location.replace('/')
  }

  return (
    <Layout>
      <main className='min-h-screen w-full flex items-center justify-center bg-primaryColor'>
        <div className='w-[450px] p-4 border  rounded-md shadow-md'>
          <img src={images.logo} className='h-[100px] w-[100px] mx-auto mb-4' />
          <h1 className='text-2xl font-bold mb-4 text-white'>Masuk</h1>
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className='space-y-4'>
              <FormField
                control={form.control}
                name='email'
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className='text-white'>User ID</FormLabel>
                    <FormControl>
                      <Input
                        // type='email'
                        placeholder='User ID'
                        {...field}
                      />
                    </FormControl>
                    <FormMessage></FormMessage>
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name='password'
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className='text-white'>Password</FormLabel>
                    <FormControl>
                      <Input
                        type='password'
                        placeholder='password'
                        {...field}
                      />
                    </FormControl>
                    <FormMessage></FormMessage>
                  </FormItem>
                )}
              />
              <Button
                disabled={status == 'loading'}
                type='submit'
                className='w-full bg-blue-700 hover:bg-blue-400'
              >
                {status == 'loading' ? (
                  <LoaderCircle className='animate-spin' />
                ) : (
                  'Masuk'
                )}
              </Button>
            </form>
          </Form>
          <p className='text-center text-sm text-white  mt-4'>
            v{constants.version}
          </p>
        </div>
      </main>
    </Layout>
  )
}
