import { useState } from 'react'
import QRCode from 'react-qr-code'
import { match } from 'ts-pattern'

import { useQuery } from '@tanstack/react-query'

import { images } from '@/assets/images/images'
import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import MarginWrapper from '@/components/margin-wrapper'
import Text from '@/components/text'
import { Button } from '@/components/ui/button'
import type {
  AsesmenAwalMedisRanap,
  Fisik,
} from '@/models/asesmen-awal-medis-ranap'
import { getAllAsesmenAwalMedisRanap } from '@/services/asesmen-keperawatan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate, formatDateTime } from '@/utils/formatDate'

import { DiagnosaTable } from './diagnosa-table'
// import { InstruksiTable } from './instruksi-table'
import { LaborTable } from './labor-table'
import PemeriksaanFisikDefault from './pemeriksaan-fisik-default'
import PemeriksaanFisikMata from './pemeriksaan-fisik-mata'
import PemeriksaanFisikTht from './pemeriksaan-fisik-tht'
import { RadiologiTable } from './radiologi-table'
import { TextTitle } from './text-title'
import { TindakanTable } from './tindakan-table'

type AsesmenAwalMedisRanapProps = {
  noreg: string
  kdBagian: string
  isReport?: boolean
}

const AsesmenAwalMedisRanap = ({
  kdBagian,
  noreg,
  isReport,
}: AsesmenAwalMedisRanapProps) => {
  const [index, setIndex] = useState(0)

  const { pasien } = usePasienStore((state) => state)

  // const { data, isLoading, isError } = useQuery({
  //   queryKey: [constants.queryKey.rekamMedis.asesmenAwalMedisRanap, noreg],
  //   queryFn: () =>
  //     getAsesmenAwalMedisRanap({
  //       noreg: noreg!,
  //       kdBagian: kdBagian!,
  //     }),
  //   enabled: !!noreg,
  // })

  const { data, isError, isLoading } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenAwalMedisRanapAll, noreg],
    queryFn: () =>
      getAllAsesmenAwalMedisRanap({
        noreg: noreg!,
        kdBagian: kdBagian!,
        tipeAsesmen: 'AWAL',
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []
  console.log('res asesmen awal medis ranap', res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <>
      {res.length > 0
        ? res.map((_, idx) => {
            return (
              <Button
                className='ml-2 my-2'
                variant={idx == index ? 'default' : 'outline'}
                key={idx}
                onClick={() => {
                  setIndex(idx)
                }}
              >
                {idx + 1}
              </Button>
            )
          })
        : null}

      <LayoutBorderNo isReport={isReport} no='RM 4.1' rev='04.2020'>
        <div className='p-2 text-xs'>
          <HeaderFormulir
            nama={pasien!.nama_pasien}
            tanggalLahir={pasien!.tgl_lahir}
            noRm={pasien!.no_rm}
            nik={pasien!.nik}
          >
            <h3>PENGKAJIAN AWAL MEDIS</h3>
            <h3>RAWAT INAP</h3>
          </HeaderFormulir>

          <div className='flex items-center justify-between'>
            <TextTitle
              title={`Tanggal MRS : ${formatDate(res[index]?.tanggal_masuk) ?? ''} ${res[index]?.jam_masuk ?? ''} WIB `}
            />
            <TextTitle
              title={`Tanggal Pengkajian : ${formatDateTime(res[index]?.tanggal) ?? ''}`}
            />
          </div>

          {/* Subyektif */}
          <div className='border border-black my-1 p-2'>
            <p className='flex-1 font-semibold'>SUBYEKTIF</p>
            <Text
              kStyle='min-w-[250px]'
              k='Keluhan Utama'
              v={res[index].keluhan_utama ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Riwayat Penyakit Sekarang'
              v={res[index].penyakit_sekarang ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Riwayat Penyakit Dahulu'
              v={res[index].penyakit_dahulu ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Riwayat Penyakit Keluarga'
              v={res[index].penyakit_keluarga ?? '-'}
            />
          </div>

          {/* Subyektif */}

          {/* Objektif */}
          <div className='border border-black my-1 p-2'>
            <div className='flex justify-between items-center'>
              <p className='flex-1 font-semibold'>OBJEKTIF</p>
            </div>
            <div className=''>
              <p>Tanda-Tanda Vital</p>
              <div className='flex items-start gap-4'>
                <div>
                  <div className='flex items-center gap-4'>
                    <p>GCS : {res[index].tanda_vital.gcs ?? '-'}</p>
                  </div>
                  <Text
                    kStyle='min-w-[50px]'
                    k='TD'
                    v={res[index].tanda_vital.td + 'mmHg'}
                  />
                  <Text
                    kStyle='min-w-[50px]'
                    k='Nadi'
                    v={res[index].tanda_vital.nadi + 'x/menit'}
                  />
                  <Text
                    kStyle='min-w-[50px]'
                    k='Suhu'
                    v={res[index].tanda_vital.temp + '°C'}
                  />
                </div>
                <div>
                  <Text
                    kStyle='min-w-[50px]'
                    k='Kesadaran'
                    v={res[index].fisik.kesadaran ?? '-'}
                  />
                  <Text
                    kStyle='min-w-[50px]'
                    k='Pernafasan'
                    v={res[index].tanda_vital.rr + 'x/menit'}
                  />
                  <Text
                    kStyle='min-w-[50px]'
                    k='SPO2'
                    v={res[index].tanda_vital.spo2 + '%'}
                  />
                </div>
              </div>
            </div>
          </div>
          {/* Objektif */}

          {/* Pemeriksaan Fisik */}
          <MarginWrapper>
            <div className='border border-black my-1 p-2'>
              <div className='flex items-center justify-between'>
                <p className='flex-1 font-semibold'>PEMERIKSAAN FISIK</p>
              </div>

              <div className='flex items-center gap-4'>
                <div className='flex-1'>
                  {renderPemeriksaanFisik(res[index].fisik)}
                </div>
              </div>
              <div className='flex items-center justify-center'>
                <img
                  src={`${import.meta.env.VITE_BASE_API_URL_RME}/app/${res[index].image_lokalis}`}
                  alt='anatomi tubuh'
                  className='object-contain h-[300px]'
                />
                {res[index].fisik.insert_user_spesialis == '' && (
                  <img
                    src={images.keterangan}
                    alt='keterangan'
                    className='object-contain h-[200px]'
                  />
                )}
              </div>
            </div>
          </MarginWrapper>
          {/* Pemeriksaan Fisik */}

          <MarginWrapper>
            {/* Pemeriksaan Penunjang */}
            <div className='border border-black my-1 p-2'>
              <p className='flex-1 font-semibold'>PEMERIKSAAN PENUNJANG</p>
              <div>
                <TextTitle title='Laboratorium' />
                <LaborTable data={res != null ? res[index].labor : []} />
              </div>
              <div>
                <TextTitle title='Pemeriksaan Lain' />
                <RadiologiTable
                  data={res != null ? res[index].radiologi : []}
                />
              </div>
            </div>
            {/* Pemeriksaan Penunjang */}
          </MarginWrapper>

          {/* Asesmen */}
          <MarginWrapper>
            <div className='border border-black my-1 p-2'>
              <div className='flex items-center justify-between'>
                <TextTitle title='Pengkajian (Diagnosa Kerja)' />
              </div>
              <DiagnosaTable data={res != null ? res[index].diagnosa : []} />
            </div>
          </MarginWrapper>
          {/* Asesmen */}

          {/* Tindakan */}
          <MarginWrapper>
            <div className='border border-black my-1 p-2'>
              <div className='flex items-center justify-between'>
                <TextTitle title='Tindakan sesuai dengan ICD-9' />
              </div>
              <TindakanTable data={res != null ? res[index].tindakan : []} />
            </div>
          </MarginWrapper>
          {/* Asesmen */}

          {/* PLANNING */}
          <MarginWrapper>
            <div className='border border-black my-1 p-2'>
              <p className='flex-1 font-semibold'>
                PLANNING :{' '}
                <span className='text-xs font-normal'>
                  Penatalaksanaan / Pengobatan / Rencana Tindakan / Konsultasi
                </span>
              </p>
              <p className='text-xs'>{res[index].terapi}</p>
            </div>
          </MarginWrapper>
          {/* PLANNING */}

          {/* PROGNOSA */}
          <div className='border border-black my-1 p-2'>
            <Text k='Prognosa' v={res[index].prognosa ?? '-'} />
          </div>
          {/* PROGNOSA */}
        </div>

        {/* Dokter Yang Memeriksa */}
        <MarginWrapper>
          <div className='p-2 mb-1 m-2'>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              {res != null && res[index].nama_dokter != '' && (
                <>
                  <p className='text-xs'>Dokter Yang Memeriksa</p>
                  <QRCode
                    value={res[index].nama_dokter ?? '-'}
                    className='w-[50px] h-[50px]'
                  />
                  <p className='text-xs'>({res[index].nama_dokter ?? '-'})</p>
                </>
              )}
            </div>
          </div>
        </MarginWrapper>
        {/* Dokter Yang Memeriksa */}
      </LayoutBorderNo>
    </>
  )
}

export default AsesmenAwalMedisRanap

function renderPemeriksaanFisik(fisik: Fisik) {
  return match(fisik.insert_user_spesialis)
    .with('MATA', () => <PemeriksaanFisikMata fisik={fisik} />)
    .with('THT', () => <PemeriksaanFisikTht fisik={fisik} />)
    .otherwise(() => (
      <PemeriksaanFisikDefault
        kepala={fisik.kepala}
        anggotaGerak={fisik.anggota_gerak}
        dada={fisik.dada}
        genetalia={fisik.alat_kelamin}
        perut={fisik.perut}
      />
    ))
}
