import { SimpleColumn } from '@/components/simple-column'
import { Penyebab } from '@/type'

interface PenyebabTableProps {
  data: Penyebab[]
}

export function PenyebabTable({ data }: PenyebabTableProps) {
  if (data.length > 0) {
    return (
      <div className='mb-2'>
        <div className='flex'>
          <SimpleColumn
            head
            name='No.'
            className='w-[50px] p-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Kode'
            className='p-1 flex-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Deskripsi'
            className='p-1 flex-1'
            className2='text-xs'
            isLast
          />
        </div>
        {data != null &&
          data.length > 0 &&
          data.map((item, i) => (
            <div className='flex' key={i}>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[50px] p-1 border-t-0'
                className2='text-xs'
              />
              <SimpleColumn
                name={item.kode}
                className='p-1 flex-1 items-start border-t-0'
                className2='text-xs'
              />
              <SimpleColumn
                name={`${item.diag}`}
                className='p-1 flex-1 items-start border-t-0'
                className2='text-xs'
                isLast
              />
            </div>
          ))}
      </div>
    )
  }
}
