import { ReactNode } from 'react'

import { TextField } from '@/features/pasien-pulang/rekam-medis/components/text-field'

interface HeaderFormulirProps {
  nama: string
  tanggalLahir: string
  noRm: string
  nik: string
  children: ReactNode
}

const HeaderFormulir = ({
  children,
  nama,
  tanggalLahir,
  noRm,
  nik,
}: HeaderFormulirProps) => {
  return (
    <div className='flex border border-black items-center mb-1'>
      <div className='flex justify-center flex-1 flex-col items-center  border-[0] border-black border-r-[1px] h-[100px] p-2'>
        <div className='text-center font-bold pt-2'>{children}</div>
      </div>
      <div className='flex-1 h-[100px] p-2'>
        <TextField title='Nama' value={nama} />
        <TextField title='Tanggal Lahir' value={tanggalLahir} />
        <TextField title='Nomor Rekam Medis' value={noRm} />
        <TextField title='NIK' value={nik} />
      </div>
    </div>
  )
}

export default HeaderFormulir
