import { AsesmenFisioterapi } from '@/models/asesmen-fisioterapi'
import type { Response } from '@/type'

import { post } from './api-2'

const getAllAsesmenFisioterapi = async (
  no_reg: string,
  kd_bagian: string,
): Promise<Response<AsesmenFisioterapi[]>> => {
  const response = await post(`/v1/asesmen-fisioterapi/all`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}

export { getAllAsesmenFisioterapi }
