import QRCode from 'react-qr-code'

// import { Link } from '@tanstack/react-router'
import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import MarginWrapper from '@/components/margin-wrapper'
import useReportResume from '@/hooks/resume'
import { formatDate } from '@/utils/formatDate'

import { DiagnosaTable } from './diagnosa-table'
import { LaborTableResume } from './labor-table-resume'
import { ObatTable } from './obat-table'
import { PenyebabTable } from './penyebab-table'
import { RadiologiTableResume } from './radiologi-table-resume'
import { TextField } from './text-field'
import { TextTitle } from './text-title'
import { TindakanTable } from './tindakan-table'

interface ReportResumeGawatDaruratProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportResumeGawatDarurat({
  isReport = false,
  noreg = '',
  no,
}: ReportResumeGawatDaruratProps) {
  // const { pasien } = usePasienStore((state) => state)

  const { res, isLoading, isError, resRanap } = useReportResume(
    noreg,
    'IGD001',
    'AWAL',
  )

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (resRanap?.indikasi_ranap.dpjp == '')
    return (
      <EmptyPlaceholder message='Data tidak ditemukan.'>
        {/* <Link to='/resume-rajal' className='hover:underline'>
          Nomor Registrasi tidak sesuai?
        </Link> */}
      </EmptyPlaceholder>
    )

  // regex meninggal
  const regex = /Meninggal/
  const isMeninggal = regex.test(resRanap.tindak_lanjut.kondisi_pulang)

  const penyebabDiagnosa = resRanap.penyebab.filter((i) => i.kode != '')

  return (
    <LayoutBorderNo isReport={isReport} no={no} rev='04.2020'>
      <div className='p-1'>
        <HeaderFormulir
          nama={res?.nama_pasien ?? ''}
          tanggalLahir={res?.tanggal_lahir ?? ''}
          noRm={res?.no_rm ?? ''}
          nik={res?.nik ?? ''}
        >
          <h3>RINGKASAN PASIEN PULANG</h3>
          <h3>(DISCHARGE SUMMARY) GAWAT DARURAT</h3>
        </HeaderFormulir>

        <div className='flex items-center justify-between'>
          <TextTitle
            title={`Tanggal Pelayanan : ${formatDate(res?.tgl_masuk) ?? res?.tgl_masuk} ${res.jam_masuk}`}
          />
          {/* <TextTitle
            title={`Tanggal Keluar : ${formatDate(res?.tgl_keluar) ?? res?.tgl_keluar}`}
          /> */}
        </div>

        <div className='flex items-center gap-4 border border-black p-1 mb-1'>
          <div className='flex-1'>
            <TextTitle title='Alasan Masuk RS' />
            {/* TODO */}
            <p className='text-xs'>{resRanap?.indikasi_ranap.keluhan_utama}</p>
            <p className='text-xs'>
              {resRanap?.indikasi_ranap.riwayat_penyakit_sekarang}
            </p>
            <div className='flex'>
              <div className='flex-1'>
                <TextTitle title='Pemeriksaan Fisik' />
                <TextField
                  title='Kepala dan leher'
                  value={resRanap?.indikasi_ranap.kepala_dan_leher}
                />
                <TextField title='Dada' value={resRanap?.indikasi_ranap.dada} />
                <TextField
                  title='Perut dan pinggang'
                  value={resRanap?.indikasi_ranap.perut_dan_pinggang}
                />
                <TextField
                  title='Anggota Gerak'
                  value={resRanap?.indikasi_ranap.anggota_gerak}
                />
                <TextField
                  title='Genetalia'
                  value={resRanap?.indikasi_ranap.genetalia_dan_anus}
                />
              </div>

              <div className='flex-1'>
                <TextTitle title='Tanda Tanda Vital' />
                <TextField
                  title='TD'
                  value={`${resRanap?.vital_sign.td} mm Hg`}
                />
                <TextField
                  title='Nadi'
                  value={`${resRanap?.vital_sign.nadi} / menit`}
                />
                <TextField
                  title='Suhu'
                  value={`${resRanap?.vital_sign.suhu} °C`}
                />
                <TextField
                  title='Pernafasan'
                  value={`${resRanap?.vital_sign.pernafasan} x / menit`}
                />
                <TextField
                  title='SpO2'
                  value={`${resRanap?.vital_sign.spo2} %`}
                />
              </div>
            </div>

            <MarginWrapper>
              <TextTitle title='Pemeriksaan Diagnostik' />
              <div>
                {resRanap.labor.length == 0 && (
                  <TextField
                    title='Laboratorium'
                    value={resRanap.pemeriksaan_diagnostik.laboratorium}
                  />
                )}
                {resRanap.radiologi.length == 0 && (
                  <TextField
                    title='Radiologi'
                    value={resRanap.pemeriksaan_diagnostik.radiologi}
                  />
                )}
                <TextField
                  title='PA'
                  value={resRanap.pemeriksaan_diagnostik.pa}
                />
                <TextField
                  title='Lainnya'
                  value={resRanap.pemeriksaan_diagnostik.lainnya}
                />
              </div>
            </MarginWrapper>
            <MarginWrapper>
              <TextTitle title='Diagnosa (ICD-10)' />
              <DiagnosaTable data={resRanap != null ? resRanap.diagnosa : []} />
              <TextTitle
                title={penyebabDiagnosa.length > 0 ? 'Penyebab Diagnosa' : ''}
              />
              <PenyebabTable data={resRanap != null ? penyebabDiagnosa : []} />
            </MarginWrapper>
            <MarginWrapper>
              <TextTitle title='Tindakan (ICD-9)' />
              <TindakanTable data={resRanap != null ? resRanap.tindakan : []} />
            </MarginWrapper>
            <MarginWrapper>
              <TextTitle title='Laboratorium' />
              <LaborTableResume data={resRanap != null ? resRanap.labor : []} />
            </MarginWrapper>
            <MarginWrapper>
              <TextTitle title='Pemeriksaan Lain' />
              <RadiologiTableResume
                data={resRanap != null ? resRanap.radiologi : []}
              />
            </MarginWrapper>
            <MarginWrapper>
              <TextTitle title='Obat selama di IGD' />
              <ObatTable isRanap data={resRanap?.obat_selama_ranap ?? []} />
              <ObatTable data={resRanap?.obat_dibawa_pulang ?? []} />
            </MarginWrapper>
            <div>
              <TextTitle title='Kondisi kesehatan pasien saat akan pulang' />
              <TextField
                title={resRanap?.tindak_lanjut.kondisi_pulang ?? '-'}
                value=''
              />
            </div>
            <div>
              <TextTitle title='Keadaan Pulang' />
              <TextField
                title={resRanap?.tindak_lanjut.cara_keluar ?? '-'}
                value=''
              />
            </div>
            <div>
              <TextTitle title='Instruksi Tindak Lanjut (Follow Up)' />
              <TextField
                title='Alasan Rujuk'
                value={resRanap?.tindak_lanjut.cara_keluar_detail ?? '-'}
              />
              <TextField
                title='Kontrol'
                value={resRanap?.tindak_lanjut.bagian != '' ? 'YA' : 'TIDAK'}
              />
              <TextField
                title='Tujuan Selanjutnya'
                value={resRanap?.tindak_lanjut.bagian}
              />
              <TextField
                title='Dokter Selanjutnya'
                value={resRanap?.tindak_lanjut.nama_dokter}
              />
              <TextField
                title='Tanggal Kontrol'
                value={
                  resRanap?.tindak_lanjut?.bagian != ''
                    ? formatDate(resRanap?.tindak_lanjut.kontrol_tanggal)
                    : ''
                }
              />
              <TextField
                title='Catatan / Edukasi'
                value={resRanap?.tindak_lanjut.instruksi_tindak_lanjut}
              />
            </div>
          </div>
        </div>

        <MarginWrapper>
          {/* Tanda Tangan */}
          <div className='ml-4'>
            <div className='py-4' />
            <div className='flex items-end justify-between'>
              <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
                {res != null && res.nama_pasien != '' ? (
                  isMeninggal && resRanap.indikasi_ranap.image_url == '' ? (
                    <div className='h-[100px]' />
                  ) : (
                    <>
                      <p className='text-xs font-medium'>
                        {isMeninggal ? 'Keluarga' : 'Pasien'}
                      </p>
                      {resRanap.indikasi_ranap.image_url != '' ? (
                        <img
                          alt='ttd'
                          src={`${import.meta.env.VITE_BASE_API_URL_RME}/app/images/ttd/${resRanap.indikasi_ranap.image_url}`}
                          className='h-[100px] w-[100px] object-contain'
                        />
                      ) : (
                        <QRCode
                          value={res.nama_pasien}
                          className='h-[50px] w-[50px]'
                        />
                      )}
                      <p className='text-xs'>( {res.nama_pasien} )</p>
                    </>
                  )
                ) : (
                  <div className='h-[100px]' />
                )}
              </div>
              <div className='w-full text-center items-center flex flex-col gap-4'>
                <p className='text-xs'>
                  Baturaja, {formatDate(res.tgl_masuk)} {res.jam_masuk}
                </p>

                {resRanap != null && resRanap!.indikasi_ranap.dpjp != '' ? (
                  <>
                    <p className='text-xs font-medium'>Dokter</p>
                    {resRanap != null ? (
                      <QRCode
                        value={resRanap!.indikasi_ranap.dpjp}
                        className='h-[50px] w-[50px]'
                      />
                    ) : (
                      <div className='h-[100px]' />
                    )}
                    <p className='text-xs'>
                      ( {resRanap!.indikasi_ranap.dpjp} )
                    </p>
                  </>
                ) : (
                  <div className='h-[100px]' />
                )}
              </div>
            </div>
          </div>
        </MarginWrapper>

        {/* Tanda Tangan */}
      </div>
    </LayoutBorderNo>
  )
}
