import { Labor } from '@/type'
import { formatDate } from '@/utils/formatDate'

export function LaborTableResume({ data }: { data: Labor[] }) {
  const group: Record<string, Labor[]> = {}

  for (let i = 0; i < data.length; i++) {
    const curr = data[i]
    const tanggal = formatDate(curr.tanggal)

    if (!group[tanggal]) {
      group[tanggal] = []
    }
    group[tanggal].push(curr)
  }

  const groups = Object.values(group)

  if (groups.length === 0) {
    return (
      <p className='text-xs text-center font-medium'>
        Tidak ada pemeriksaan laboratorium
      </p>
    )
  }

  return (
    <div className='border border-black'>
      {groups.map((items, idx) => (
        <div key={idx}>
          <div className='p-1 bg-gray-300'>
            <p className='text-xs'>{formatDate(items[0].tanggal)}</p>
          </div>
          {items.map((item: Labor, index) => {
            const abnormalPenlab = item.penlab.filter(
              (i) => i.kategori !== 'NORMAL'
            )
            const hasAbnormal = abnormalPenlab.length > 0

            return (
              <div key={`labor-${index}`}>
                <div className='p-1 bg-gray-400'>
                  <h3 className='font-bold text-xs'>
                    {item.nama_kelompok}
                  </h3>
                </div>

                {hasAbnormal ? (
                  <div className='flex items-start justify-between'>
                    <div className='w-full text-center border-r border-black'>
                      <div className='border-b border-black'>
                        <h3 className='font-medium py-1 text-xs'>Deskripsi</h3>
                      </div>
                      {abnormalPenlab.map((p, i) => (
                        <p
                          key={`deskripsi-${index}-${i}`}
                          className='text-start px-2 text-xs'
                        >
                          {p.pemeriksaan_deskripsi}
                        </p>
                      ))}
                    </div>

                    <div className='w-full text-center border-r border-black'>
                      <div className='border-b border-black'>
                        <h3 className='font-medium py-1 text-xs'>Normal</h3>
                      </div>
                      {abnormalPenlab.map((p, i) => (
                        <p
                          key={`normal-${index}-${i}`}
                          className='text-start px-2 text-xs'
                        >
                          {p.normal} {p.satuan}
                        </p>
                      ))}
                    </div>

                    <div className='w-full text-center border-r border-black'>
                      <div className='border-b border-black'>
                        <h3 className='font-medium py-1 text-xs'>Penanda</h3>
                      </div>
                      {abnormalPenlab.map((p, i) => (
                        <p
                          key={`penanda-${index}-${i}`}
                          className='text-center px-2 text-xs'
                        >
                          {p.kategori === 'ATAS' ? '↑' : '↓'}
                        </p>
                      ))}
                    </div>

                    <div className='w-full text-center border-black'>
                      <div className='border-b border-black'>
                        <h3 className='font-medium py-1 text-xs'>Hasil</h3>
                      </div>
                      {abnormalPenlab.map((p, i) => (
                        <p
                          key={`hasil-${index}-${i}`}
                          className='text-start px-2 text-xs'
                        >
                          {p.hasil} {p.satuan}
                        </p>
                      ))}
                    </div>
                  </div>
                ) : (
                  <p className='text-xs text-center font-medium'>Terlampir</p>
                )}
              </div>
            )
          })}
        </div>
      ))}
    </div>
  )
}
