import type { MonitoringPasienDarurat } from '@/models/monitoring-pasien-darurat'
import type { Response } from '@/type'

import { post } from './api-2'

const getMonitoringPasienDarurat = async (
  no_reg: string,
): Promise<Response<MonitoringPasienDarurat>> => {
  const response = await post(`/v1/monitoring-pasien-darurat`, { no_reg })

  return response.data
}

export { getMonitoringPasienDarurat }
