import type { PersiapanOperasiResponse } from '@/models/persiapan-operasi'
import type { Response } from '@/type'

import { post } from './api-2'

const getReportPersiapanOperasi = async ({
  noreg,
  no_rm,
}: {
  noreg: string
  no_rm: string
}): Promise<Response<PersiapanOperasiResponse>> => {
  const response = await post(`/v1/persiapan-operasi/report-web`, {
    noreg,
    no_rm,
  })

  return response.data
}

export { getReportPersiapanOperasi }
