import { ChevronDown, Target, Wrench } from 'lucide-react'

import { useState } from 'react'

import { cn, toTarget } from '@/lib/utils'
import {
  type DeskripsiSIKI,
  KATEGORI_INTERVENSI,
  KATEGORI_KRITERIA,
  type KriteriaHasil,
  type LuaranSLKI,
} from '@/models/sdki-slki'

import { intervensiStyle, kriteriaStyle } from '../design'
import { kriteriaTerisi } from '../utils'
import { Chip, KodeBadge } from './kode-badge'

/** Header kartu yang bisa dibuka/tutup. */
function CardHeader({
  open,
  onToggle,
  icon,
  code,
  title,
  children,
}: {
  open: boolean
  onToggle: () => void
  icon: React.ReactNode
  code: string
  title: string
  children?: React.ReactNode
}) {
  return (
    <button
      type='button'
      onClick={onToggle}
      className='flex w-full items-start gap-2.5 p-3 text-left transition-colors hover:bg-slate-50/80'
    >
      <ChevronDown
        className={cn(
          'mt-1 size-4 shrink-0 text-slate-400 transition-transform duration-200',
          !open && '-rotate-90',
        )}
      />
      <span className='mt-0.5 shrink-0 text-slate-400'>{icon}</span>
      <div className='min-w-0 flex-1'>
        <div className='flex flex-wrap items-center gap-2'>
          <KodeBadge code={code} />
          <span className='text-[13px] font-semibold leading-tight text-slate-800'>
            {title}
          </span>
          {children}
        </div>
      </div>
    </button>
  )
}

/** Deretan skala 1-5 dengan label hasil `toTarget`. */
function SkalaNilai({ kategori }: { kategori: string }) {
  return (
    <div className='flex flex-wrap gap-1'>
      {[1, 2, 3, 4, 5].map((skor) => (
        <span
          key={skor}
          className='inline-flex items-center gap-1 rounded border border-slate-200 bg-white px-1.5 py-0.5 text-[10px] text-slate-500'
        >
          <span className='font-medium tabular-nums text-slate-600'>
            {skor}
          </span>
          {toTarget(kategori, skor)}
        </span>
      ))}
    </div>
  )
}

function KriteriaList({
  kategori,
  items,
}: {
  kategori: string
  items: KriteriaHasil[]
}) {
  const isi = kriteriaTerisi(items)
  if (isi.length === 0) return null

  const style = kriteriaStyle(kategori)

  return (
    <div className='space-y-1.5'>
      <div className='flex items-center gap-1.5'>
        <span className={cn('size-1.5 rounded-full', style.dot)} />
        <span className='text-[10px] font-semibold uppercase tracking-wider text-slate-500'>
          {kategori}
        </span>
        <span className='text-[10px] tabular-nums text-slate-400'>
          ({isi.length})
        </span>
      </div>
      <ul className='space-y-1.5'>
        {isi.map((item) => (
          <li
            key={`${item.id_kriteria}-${item.nama}`}
            className='flex flex-col gap-1 rounded-lg bg-slate-50/70 px-2.5 py-1.5'
          >
            <div className='flex flex-wrap items-center gap-1.5'>
              <span className='text-[11px] font-medium tabular-nums text-slate-400'>
                {item.no_urut}.
              </span>
              <span className='text-xs text-slate-700'>{item.nama}</span>
              {item.tanda && (
                <Chip className='bg-amber-50 text-amber-700 ring-amber-200'>
                  tanda
                </Chip>
              )}
            </div>
            <SkalaNilai kategori={kategori} />
          </li>
        ))}
      </ul>
    </div>
  )
}

/** Kartu satu luaran (SLKI) beserta kriteria hasilnya. */
export function LuaranCard({ luaran }: { luaran: LuaranSLKI }) {
  const [open, setOpen] = useState(true)

  const total = KATEGORI_KRITERIA.reduce(
    (acc, { field }) => acc + kriteriaTerisi(luaran[field]).length,
    0,
  )

  return (
    <div className='overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition-shadow hover:shadow-md'>
      <CardHeader
        open={open}
        onToggle={() => setOpen((prev) => !prev)}
        icon={<Target className='size-4' />}
        code={luaran.kode_slki}
        title={luaran.judul}
      >
        {luaran.ekspetasi && (
          <Chip className='bg-emerald-50 text-emerald-700 ring-emerald-200'>
            {luaran.ekspetasi}
          </Chip>
        )}
        <span className='text-[10px] tabular-nums text-slate-400'>
          {total} kriteria
        </span>
      </CardHeader>

      {luaran.defenisi && (
        <p className='border-t border-slate-100 bg-slate-50/50 px-3 py-2 pl-11 text-[11px] italic leading-relaxed text-slate-500'>
          {luaran.defenisi}
        </p>
      )}

      {open && (
        <div className='space-y-3 border-t border-slate-100 p-3 pl-11'>
          {KATEGORI_KRITERIA.map(({ key, field }) => (
            <KriteriaList
              key={key}
              kategori={key}
              items={luaran[field] ?? []}
            />
          ))}
        </div>
      )}
    </div>
  )
}

function IntervensiGroup({
  kategori,
  items,
}: {
  kategori: string
  items: NonNullable<DeskripsiSIKI['observasi']>
}) {
  if (items.length === 0) return null

  const style = intervensiStyle(kategori)

  return (
    <div className='space-y-1.5'>
      <div className='flex items-center gap-1.5'>
        <span className={cn('size-1.5 rounded-full', style.dot)} />
        <span className='text-[10px] font-semibold uppercase tracking-wider text-slate-500'>
          {kategori}
        </span>
        <span className='text-[10px] tabular-nums text-slate-400'>
          ({items.length})
        </span>
      </div>
      <ul className='space-y-1'>
        {items.map((item) => (
          <li
            key={`${item.id_siki}-${item.no_urut}-${item.deskripsi}`}
            className='flex gap-2 rounded-lg bg-slate-50/70 px-2.5 py-1.5'
          >
            <span className='text-[11px] font-medium tabular-nums text-slate-400'>
              {item.no_urut}.
            </span>
            <span className='text-xs leading-relaxed text-slate-700'>
              {item.deskripsi}
            </span>
          </li>
        ))}
      </ul>
    </div>
  )
}

/** Kartu satu intervensi (SIKI) beserta deskripsi per kategori. */
export function IntervensiCard({ intervensi }: { intervensi: DeskripsiSIKI }) {
  const [open, setOpen] = useState(true)

  const total = KATEGORI_INTERVENSI.reduce(
    (acc, { field }) => acc + (intervensi[field]?.length ?? 0),
    0,
  )

  return (
    <div className='overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition-shadow hover:shadow-md'>
      <CardHeader
        open={open}
        onToggle={() => setOpen((prev) => !prev)}
        icon={<Wrench className='size-4' />}
        code={intervensi.kode}
        title={intervensi.judul}
      >
        <span className='text-[10px] tabular-nums text-slate-400'>
          {total} tindakan
        </span>
      </CardHeader>

      {open && (
        <div className='space-y-3 border-t border-slate-100 p-3 pl-11'>
          {KATEGORI_INTERVENSI.map(({ key, field }) => (
            <IntervensiGroup
              key={key}
              kategori={key}
              items={intervensi[field] ?? []}
            />
          ))}
        </div>
      )}
    </div>
  )
}
