import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import type { PengkajianAwalMppModel } from '@/models/pengkajian-awal-mpp'
import { getPengkajianAwalMpp } from '@/services/pengkajian-awal-mpp'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportPengkajianAwalMppProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
  noRm?: string
}

// ponytail: server balas 200 + zero-value struct kalau row tidak ada; `id === 0` jadi sentinel "kosong".
// Ganti ke cek field lain kalau backend mulai kirim 404.
const init: PengkajianAwalMppModel = {
  id: 0,
  insert_dttm: '',
  noreg: '',
  kd_bagian: '',
  pelayanan: '',
  insert_user_id: '',
  tanggal: '',
  jam: '',
  skrining_awal: '',
  identifikasi_masalah: '',
  identifikasi_harapan: '',
  perencanaan: '',
  dpjp: '',
  diagnosa: '',
  tgl_mrs: '',
  jaminan: '',
  manajer_pelayanan_pasien: '',
  pengkajian: {
    kondisi: '',
    riwayat_kesehatan: '',
    perilaku_psikososial: '',
    kesehatan_mental: '',
    tersedia_dukungan: '',
    finansial: '',
    asuransi: '',
    riwayat_penggunaan_obat: '',
    riwayat_trauma: '',
    pemahaman_dan_kepatuhan: '',
    perubahan_kondisi: '',
    kemampuan_menerima_perubahan: '',
    keterkaitan_hukum: '',
    domisili: '',
    tempat_tinggal_sementara_dirawat: '',
  },
  petugas: '',
}

// Paritas `titleBox` di report Flutter: blok disembunyikan kalau value kosong.
const Field = ({ title, value }: { title: string; value?: string }) => {
  if (!value) return null
  return (
    <div className='mb-2'>
      <p className='text-xs font-bold'>{title}</p>
      <p className='text-xs whitespace-pre-wrap'>{value}</p>
    </div>
  )
}

const ReportPengkajianAwalMpp = ({
  isReport,
  noreg,
  kdBagian,
}: ReportPengkajianAwalMppProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pengkajianAwalMpp, noreg],
    queryFn: () =>
      getPengkajianAwalMpp({ no_reg: noreg!, kd_bagian: kdBagian! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : init

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.id === 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  // ponytail: nomor 14 & 15 + typo "keuanagn" diperbaiki dari report Flutter (output cetak baru).
  const items: [string, string][] = [
    [
      '1. Kondisi fisik, kognitif, status fungsional dan kemandirian :',
      res.pengkajian.kondisi,
    ],
    ['2. Riwayat Kesehatan :', res.pengkajian.riwayat_kesehatan],
    ['3. Perilaku psikososiokultural  :', res.pengkajian.perilaku_psikososial],
    ['4. Kesehatan Mental', res.pengkajian.kesehatan_mental],
    [
      '5. Tersedia dukungan keluarga, kemampuan merawat dari pemberi asuhan',
      res.pengkajian.tersedia_dukungan,
    ],
    [
      '6. Finansial / sumber keuangan dari pasien / keluarga',
      res.pengkajian.finansial,
    ],
    ['7. Asuransi / Penjaminan ', res.pengkajian.asuransi],
    [
      '8. Riwayat penggunaan obat ( Alternatif / Napza )',
      res.pengkajian.riwayat_penggunaan_obat,
    ],
    ['9. Riwayat trauma atau kekerasan', res.pengkajian.riwayat_trauma],
    [
      '10. Pemahaman & kepatuhan terhadap kesehatan ( kondisi penyakit )',
      res.pengkajian.pemahaman_dan_kepatuhan,
    ],
    [
      '11. Terjadi perubahan / penurunan kondisi pasien dalam perawatan',
      res.pengkajian.perubahan_kondisi,
    ],
    [
      '12. Kemampuan menerima perubahan ( mekanisme koping )',
      res.pengkajian.kemampuan_menerima_perubahan,
    ],
    [
      '13. Keterkaitan dengan aspek legal atau hukum :',
      res.pengkajian.keterkaitan_hukum,
    ],
    ['14. Domisili pasien berasal dari', res.pengkajian.domisili],
    [
      '15. Tempat tinggal sementara pasien / keluarga, selama dirawat',
      res.pengkajian.tempat_tinggal_sementara_dirawat,
    ],
  ]

  return (
    <LayoutBorderNo isReport={isReport} no='RM 21' rev='01.2020'>
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={formatDate(pasien?.tgl_lahir ?? '')}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3 className='text-xs font-bold text-center py-3 whitespace-pre-wrap'>
            ASESMEN AWAL MPP
            <br />
            FORM A
          </h3>
        </HeaderFormulir>
      </div>

      <div className='mx-6 mb-2 border border-black p-2'>
        <Field title='DPJP' value={res.dpjp} />
        <Field title='DIAGNOSA MEDIS' value={res.diagnosa} />
        <Field title='TANGGAL MRS' value={res.tgl_mrs} />
        <Field title='JAMINAN' value={res.jaminan} />
        <Field
          title='MANAJER PELAYANAN PASIEN'
          value={res.manajer_pelayanan_pasien}
        />
        <hr className='my-2 border-black' />
        <Field title='SKRINING AWAL PASIEN' value={res.skrining_awal} />
        <hr className='my-2 border-black' />

        <p className='text-xs font-bold'>
          PENGKAJIAN MANAJEMEN PELAYANAN PASIEN
        </p>
        <div className='mt-2'>
          {items.map(([title, value]) => (
            <Field key={title} title={title} value={value} />
          ))}
        </div>

        <hr className='my-2 border-black' />
        <Field title='IDENTIFIKASI MASALAH' value={res.identifikasi_masalah} />
        <Field title='IDENTIFIKASI HARAPAN' value={res.identifikasi_harapan} />
        <hr className='my-2 border-black' />
        <Field title='PERENCANAAN' value={res.perencanaan} />
      </div>

      <div className='mx-6 mb-2 border border-black p-2 flex items-start justify-between'>
        <div>
          <p className='text-xs font-medium'>Tanggal dan Jam Pengkajian</p>
          <p className='text-xs'>
            {formatDate(res.tanggal)} {res.jam} WIB
          </p>
        </div>
        <div className='flex flex-col items-center justify-center'>
          <p className='text-xs font-medium'>Nama Petugas MPP</p>
          <QRCode value={res.petugas!} className='h-[50px] w-[50px] my-4' />
          <p className='text-xs'>{res.petugas!}</p>
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default ReportPengkajianAwalMpp
