/**
 * Token warna untuk chip kategori.
 *
 * Dipisah dari komponen agar tidak ada duplikasi string kelas dan supaya
 * penambahan kategori baru cukup diubah di satu tempat.
 */

export interface ChipStyle {
  /** Kelas untuk chip kecil (bg + text + ring). */
  chip: string
  /** Kelas untuk titik indikator. */
  dot: string
  /** Kelas untuk aksen kiri/border kartu. */
  accent: string
}

const NEUTRAL: ChipStyle = {
  chip: 'bg-slate-50 text-slate-600 ring-slate-200',
  dot: 'bg-slate-400',
  accent: 'border-slate-200',
}

/** Warna kategori kriteria hasil (SLKI). */
export const KATEGORI_KRITERIA_STYLE: Record<string, ChipStyle> = {
  Menurun: {
    chip: 'bg-rose-50 text-rose-700 ring-rose-200',
    dot: 'bg-rose-400',
    accent: 'border-rose-200',
  },
  Meningkat: {
    chip: 'bg-emerald-50 text-emerald-700 ring-emerald-200',
    dot: 'bg-emerald-400',
    accent: 'border-emerald-200',
  },
  Memburuk: {
    chip: 'bg-amber-50 text-amber-700 ring-amber-200',
    dot: 'bg-amber-400',
    accent: 'border-amber-200',
  },
}

/** Warna kategori intervensi (SIKI). */
export const KATEGORI_INTERVENSI_STYLE: Record<string, ChipStyle> = {
  Observasi: {
    chip: 'bg-sky-50 text-sky-700 ring-sky-200',
    dot: 'bg-sky-400',
    accent: 'border-sky-200',
  },
  Terapetutik: {
    chip: 'bg-violet-50 text-violet-700 ring-violet-200',
    dot: 'bg-violet-400',
    accent: 'border-violet-200',
  },
  Edukasi: {
    chip: 'bg-emerald-50 text-emerald-700 ring-emerald-200',
    dot: 'bg-emerald-400',
    accent: 'border-emerald-200',
  },
  Kolaborasi: {
    chip: 'bg-amber-50 text-amber-700 ring-amber-200',
    dot: 'bg-amber-400',
    accent: 'border-amber-200',
  },
}

export function kriteriaStyle(kategori: string): ChipStyle {
  return KATEGORI_KRITERIA_STYLE[kategori] ?? NEUTRAL
}

export function intervensiStyle(kategori: string): ChipStyle {
  return KATEGORI_INTERVENSI_STYLE[kategori] ?? NEUTRAL
}
