import type { AsesmenDokterIgd, Response } from '@/type'

import { get } from './api'

const getAsesmenDokterIgd = async ({
  noreg,
  tipeAsesmen,
}: {
  noreg: string
  tipeAsesmen: string
}): Promise<Response<AsesmenDokterIgd>> => {
  const response = await get(`/v1/asesmen-dokter-igd/${noreg}/${tipeAsesmen}`)

  return response.data
}

export { getAsesmenDokterIgd }
