import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { ReportPermintaanDietModel } from '@/models/permintaan-diet'
import { getPermintaanDietReport } from '@/services/permintaan-diet'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

import { TextField } from './text-field'

interface ReportPermintanDietProps {
  isReport?: boolean
  noreg?: string
  no?: string
  kdBagian?: string
}

const ReportPermintanDiet = ({ isReport, noreg }: ReportPermintanDietProps) => {
  const { pasien } = usePasienStore((state) => state)

  const init: ReportPermintaanDietModel = {
    data: {
      id: 0,
      insert_dttm: '',
      update_dttm: '',
      noreg: '',
      insert_user_id: '',
      kd_bagian: '',
      alergi_makanan: '',
      pantangan_makanan: '',
      diagnosa_awal_igd: '',
      pengobatan_penting: '',
      diit: '',
      jenis_diet: '',
      nama_perawat: '',
    },
    pasien: {
      nama_pasien: '',
      nik: '',
      tgl_lahir: '',
      no_rm: '',
      alamat: '',
      no_hp: '',
      umur: 0,
      jenis_kelamin: '',
    },
    fisik: {
      tb: '',
      bb: '',
    },
  }

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.permintaanDiet, noreg],
    queryFn: () =>
      getPermintaanDietReport({
        kd_bagian: 'IGD001',
        no_reg: noreg!,
        no_rm: pasien!.no_rm,
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : init
  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.data.noreg == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 5b' rev='01.2020'>
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={pasien?.tgl_lahir ?? ''}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3 className='text-xs font-bold text-center py-3'>
            FORMULIR PERMINTAAN DIET
          </h3>
        </HeaderFormulir>

        <div className='gap-4 border border-black p-1 mb-1'>
          <div className='mb-4'>
            <TextField title='Alergi Makanan' value={res.data.alergi_makanan} />
            <TextField
              title='Pantangan Makanan'
              value={res.data.pantangan_makanan}
            />
          </div>
          <div className='mb-4'>
            <p className='font-semibold'>Terhadap Penderita</p>
            <TextField title='Nama' value={res.pasien.nama_pasien} />
            <TextField title='Jenis Kelamin' value={res.pasien.jenis_kelamin} />
            <div className='flex items-center gap-4'>
              <TextField title='TB' value={res.fisik.tb} />
              <TextField title='BB' value={res.fisik.bb} />
            </div>
          </div>
          <TextField
            title='Diagnosa Awal IGD'
            value={res.data.diagnosa_awal_igd}
          />
          <TextField
            title='Pengobatan Penting'
            value={res.data.pengobatan_penting}
          />
          <TextField title='Diit' value={res.data.diit} />
          <TextField
            title='Jenis Diet menurut penyakitnya'
            value={res.data.jenis_diet}
          />

          {/* Tanda Tangan */}
          <div className='ml-4'>
            <div className='py-10' />
            <div className='flex items-end justify-between'>
              <div className='w-full text-center flex flex-col justify-between items-center gap-2'>
                <p className='font-medium'>
                  Baturaja, {formatDate(res.data.insert_dttm)}
                </p>
                <p className='font-medium'>Perawat</p>
                {res.data.nama_perawat ? (
                  <>
                    <QRCode
                      value={res.data.nama_perawat}
                      className='h-[50px] w-[50px]'
                    />
                    <p>( {res.data.nama_perawat} )</p>
                  </>
                ) : (
                  <div className='h-[50px]' />
                )}
              </div>
            </div>
          </div>
          {/* Tanda Tangan */}
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default ReportPermintanDiet
