import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { TextField } from '@/components/text-field'
import { getGeneralConsentReport } from '@/services/general-consent'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface GeneralConsentRanapProps {
  isReport?: boolean
  noreg?: string
}

export default function GeneralConsentRanap({
  isReport = false,
  noreg,
}: GeneralConsentRanapProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.rekamMedis, pasien?.no_rm],
    queryFn: () => getGeneralConsentReport(pasien!.no_rm, noreg!, 'ranap'),
    enabled: !!pasien?.no_rm,
  })

  const res = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 1b1' rev='03.2020'>
      <div className='p-4 text-xs'>
        <h3 className='text-xs font-bold text-center py-3'>
          PERSETUJUAN UMUM <br />
          (GENERAL CONSENT) RAWAT INAP
        </h3>
        <div className='px-5'>
          <p className='text-xs'>Yang bertanda tangan di bawah ini :</p>
          <TextField title='Nama' value={res?.penangung_jawab.nama} />
          <TextField title='Alamat' value={res?.penangung_jawab.alamat} />
          <TextField title='No.HP' value={res?.penangung_jawab.no_hp} />
          <TextField
            title='Hubungan dengan pasien'
            value={res?.penangung_jawab.hub_pasien}
          />
        </div>

        <div className='p-5'>
          <p className='text-xs mb-2'>
            Selaku Pasien / Wali hukum di Rumah Sakit Santo Antonio dengan ini
            menyatakan persetujuan :
          </p>
          <h3 className='text-black font-semibold ml-1'>
            A. PERSETUJUAN UNTUK PERAWATAN DAN PENGOBATAN
          </h3>
          <p className='text-xs mb-2 ml-5'>
            1. Saya mengetahui bahwa saya/ pasien memiliki kondisi yang
            membutuhkan perawatan medis, saya mengizinkan dokter dan profesional
            kesehatan lainnya untuk melakukan prosedur diagnostik dan untuk
            memberikan pengobatan medis seperti yang diperlukan dalam penilaian
            profesional mereka. Prosedur diagnostik dan perawatan medis termasuk
            tetapi tidak terbatas pada electrocardiograms, x-ray, tes darah,
            terapi fisik, dan pemberian obat tetapi juga perawatan rutin dan
            prosedur seperti pemasangan infuse atau suntikan dan evaluasi (
            missal : wawancara dan pemeriksaan fisik ).
          </p>
          <p className='text-xs mb-2 ml-5'>
            2. Persetujuan yang saya / pasien berikan tidak termasuk persetujuan
            untuk prosedur / tindakan invansive ( misalnya : operasi ) atau
            tindakan yang mempunyai resiko tinggi yang akan dimintakan informed
            consent (Pernyataan Persetujuan) kepada saya/pasien untuk saya
            tandatangani, dan saya sadar bahwa tindakan tersebut mengandung
            resiko medis.
          </p>

          <p className='text-xs mb-2 ml-5'>
            3. Jika saya / pasien memutuskan untuk menghentikan perawatan medis
            untuk diri saya / pasien sendiri. Saya memahami dan menyadari bahwa
            Rumah Sakit St. Antonio atau dokter tidak bertanggung jawab atas
            hasil yang merugikan saya / pasien.
          </p>

          <h3 className='text-black font-semibold ml-1'>
            B. PERSETUJUAN PELEPASAN INFORMASI
          </h3>

          <p className='text-xs mb-2 ml-5'>
            1. Saya mengetahui dan menyetujui bahwa berdasarkan Peraturan
            Menteri Kesehatan Nomor 24 Tahun 2022 tentang Rekam Medis. Fasilitas
            pelayanan kesehatan wajib membuka akses dan mengirim data rekam
            medis kepada Kementerian Kesehatan melalui Platfrom SATUSEHAT
          </p>

          <p className='text-xs mb-2 ml-5'>
            2. Menyetujui untuk menerima dan membuka data pasien dari fasilitas
            pelayanan kesehatan lainnya melalui SATUSEHAT untuk kepentingan
            pelayanan kesehatan dan/atau rujukan. <br />
            <span className='whitespace-pre-wrap font-semibold'>
              {res?.penangung_jawab.pewenang}
            </span>
          </p>

          <p className='text-xs mb-2 ml-5'>
            3. Memahami bahwa informasi yang ada didalam diri pasien termasuk
            data rekam medis pasien yang akan digunakan untuk kepentingan
            perawatan medis pasien di RS Santo Antonio
          </p>

          <p className='text-xs mb-2 ml-5'>
            4. Memberi persetujuan kepada pihak RS Santo Antonio untuk
            memberikan informasi rekam medis pasien kepada pihak instansi/
            asuransi/ TPA bila diperlukan untuk proses klaim asuransi/
            perusahaan yang memberikan pertanggungan.
          </p>

          <h3 className='text-black font-semibold ml-1'>
            C. BARANG – BARANG MILIK PASIEN
          </h3>

          <p className='text-xs mb-2 ml-5'>
            1. Saya telah memahami bahwa Rumah Sakit St. Antonio tidak
            bertanggung jawab atas semua kehilangan barang-barang milik saya dan
            saya secara pribadi bertanggung jawab atas barang-barang berharga
            yang saya miliki, termasuk namun tidak terbatas pada
            uang,perhiasan,buku cek,kartu kredit,handphone atau barang lainnya.
            Dan apabila saya membutuhkan maka saya dapat menitipkan
            barang-barang saya kepada rumah sakit.{' '}
          </p>

          <p className='text-xs mb-2 ml-5'>
            2. Saya juga mengerti bahwa saya harus memberitahu/menitipkan pada
            RS jika saya memiliki gigi palsu,kacamata,lensa kontak,prosthetics
            atau barang lainnya yang saya butuhkan untuk diamankan
          </p>

          <h3 className='text-black font-semibold ml-1'>
            D. HAK DAN TANGGUNG JAWAB PASIEN
          </h3>

          <p className='text-xs mb-2 ml-5'>
            1. Saya memiliki hak untuk mengambil bagian dalam keputusan mengenai
            penyakit saya dan dalam hal perawatan medis dan rencana pengobatan.
          </p>

          <p className='text-xs mb-2 ml-5'>
            2. Saya telah mendapat informasi tentang “HAK DAN TANGGUNG JAWAB
            PASIEN” di Rumah Sakit Santo Antonio melalui leaflet dan banner yang
            disediakan oleh petugas.
          </p>

          <h3 className='text-black font-semibold ml-1'>
            E. KEINGINAN PRIVASI PASIEN
          </h3>

          <p className='text-xs mb-2 ml-5'>
            1. Saya mengizinkan Rumah Sakit memberi akses bagi keluarga dan
            handai taulan serta orang – orang yang akan menengok / menemui saya
          </p>

          <p className='text-xs mb-2 ml-5'>
            2. Apabila ada tamu / pengunjung yang tidak saya inginkan, maka saya
            akan melaporkan kepada petugas jaga yaitu atas nama :{' '}
            <strong>{res?.penangung_jawab.privasi}</strong>
          </p>

          <p className='text-xs mb-2 ml-5'>
            3. Saya memberi kuasa kepada setiap dan seluruh tenaga kesehatan,
            perawat Rumah Sakit Santo Antonio yang sedang melanjutkan
            pendidikan, dokter internship yang merawat saya untuk memeriksa dan
            atau memberitahukan informasi kesehatan saya kepada pemberi
            kesehatan lain yang turut merawat saya selama di rumah sakit ini.
          </p>

          <h3 className='text-black font-semibold ml-1'>
            F. INFORMASI RAWAT INAP
          </h3>

          <p className='text-xs mb-2 ml-5'>
            1. Saya telah menerima informasi tentang peraturan yang diberlakukan
            oleh rumah sakit dan saya beserta keluarga bersedia untuk
            mematuhinya, termasuk akan mematuhi jam berkunjung pasien sesuai
            dengan aturan di Rumah Sakit Santo Antonio, termasuk larangan
            merokok di area Rumah Sakit St. Antonio.
          </p>

          <p className='text-xs mb-2 ml-5'>
            2. Anggota keluarga saya yang menunggu saya bersedia untuk selalu
            memakai tanda pengenal khusus yang diberikan oleh Rumah sakit dan
            demi keamanan seluruh pasien setiap keluarga dan siapapun yang akan
            mengunjungi saya diluar jam berkunjung bersedia untuk
            diminta/diperiksa identitasnya.
          </p>

          <h3 className='text-black font-semibold ml-1'>G. INFORMASI BIAYA</h3>

          <p className='text-xs mb-2 ml-5'>
            Saya memahami tentang informasi biaya pengobatan atau biaya tindakan
            yang dijelaskan oleh petugas Rumah Sakit St. Antonio, diantaranya
            adalah pembiayaan rawat inap saat ini menggunakan pembiayaan{' '}
            <strong>{res?.penangung_jawab.pembiayaan}</strong> Dengan jatah /
            plafon / kamar yang dipilih adalah kelas{' '}
            <strong>{res?.penangung_jawab.hak_kelas}</strong> Penempatan kamar
            saat ini adalah Ruang{' '}
            <strong>
              {res?.penangung_jawab.ruangan} - {res?.penangung_jawab.kamar_no}
            </strong>{' '}
            Keterangan <strong>{res?.penangung_jawab.keterangan}</strong> (
            diisi jika penempatan kamar belum sesuai dengan haknya )
          </p>

          <h3 className='text-black font-semibold ml-1'>H. TANDA TANGAN</h3>

          <p className='text-xs mb-2 ml-5'>
            Dengan tanda tangan saya di bawah ini, saya menyatakan bahwa saya
            telah membaca dan memahami item pada Persetujuan Umum / General
            Consent.
          </p>
        </div>

        {/* Tanda Tangan */}
        <div className='ml-4'>
          <div className='py-10' />
          <div className='flex items-end justify-between'>
            <div className='w-full text-center flex flex-col justify-between items-center gap-2'>
              <p className='text-xs'>
                Baturaja, {formatDateTime(res!.penangung_jawab.insert_dttm)}
              </p>
              <p className='font-medium'>Petugas pemberi informasi</p>
              {res != null ? (
                res.penangung_jawab.nama_perawat ? (
                  <>
                    <QRCode
                      value={res.penangung_jawab.nama_perawat}
                      className='h-[50px] w-[50px]'
                    />
                    <p>( {res.penangung_jawab.nama_perawat} )</p>
                  </>
                ) : (
                  <div className='h-[50px]' />
                )
              ) : (
                <div className='h-[50px]' />
              )}
            </div>
            <div className='w-full text-center items-center flex flex-col gap-2'>
              <p className='font-medium'>Pasien/Penanggung Jawab</p>
              {res != null && res.penangung_jawab.nama != '' ? (
                <>
                  {res.penangung_jawab.nama != null ? (
                    <div>
                      {res?.penangung_jawab.image_url != '' ? (
                        <img
                          alt='ttd'
                          src={`${import.meta.env.VITE_BASE_API_URL_RME}/app/images/ttd/${res?.penangung_jawab.image_url}`}
                          className='h-[100px] w-[100px] object-contain'
                        />
                      ) : (
                        <QRCode
                          value={pasien?.nama_pasien || ''}
                          className='h-[50px] w-[50px]'
                        />
                      )}
                    </div>
                  ) : (
                    <div className='h-[50px]' />
                  )}
                  <p>( {res.penangung_jawab.nama} )</p>
                </>
              ) : (
                <>
                  {pasien?.nama_pasien != null ? (
                    <div>
                      {res?.penangung_jawab.image_url != '' ? (
                        <img
                          alt='ttd'
                          src={`${import.meta.env.VITE_BASE_API_URL_RME}/app/images/ttd/${res?.penangung_jawab.image_url}`}
                          className='h-[100px] w-[100px] object-contain'
                        />
                      ) : (
                        <QRCode
                          value={pasien.nama_pasien}
                          className='h-[50px] w-[50px]'
                        />
                      )}
                    </div>
                  ) : (
                    <div className='h-[50px]' />
                  )}
                  <p>( {pasien!.nama_pasien} )</p>
                </>
              )}
            </div>
          </div>
        </div>
        {/* Tanda Tangan */}
      </div>
    </LayoutBorderNo>
  )
}
