/**
 * Checklist kosong. Array dibuat baru per kolom supaya tidak ada referensi
 * yang terbagi antar field (bug klasik `{ ...empty }`).
 */
export function createEmptyChecklist(): TriaseChecklist {
  return CHECKLIST_FIELD_KEYS.reduce((acc, fieldKey) => {
    acc[fieldKey] = { p1: [], p2: [], p3: [], p4: [] }
    return acc
  }, {} as TriaseChecklist)
}

