import { ReactNode, useState } from 'react'

const MarginWrapper = ({ children }: { children: ReactNode }) => {
  const [margin, setMargin] = useState({
    top: 0,
    bottom: 0,
  })

  return (
    <div
      className='flex relative'
      style={{ marginTop: margin.top, marginBottom: margin.bottom }}
    >
      <div className='flex-1'>{children}</div>
      <div className='font-black flex flex-col gap-2 absolute right-0 top-0 hide-when-print items-end'>
        <div className='flex gap-2  p-2'>
          <Btn
            title='Top +'
            onClick={() => {
              setMargin({ ...margin, top: margin.top + 4 })
            }}
          />
          <Btn
            title='Top -'
            onClick={() => {
              setMargin({ ...margin, top: margin.top - 4 })
            }}
          />
        </div>
        <div className='flex gap-2 p-2'>
          <Btn
            title='Bottom +'
            onClick={() => {
              setMargin({ ...margin, bottom: margin.bottom + 4 })
            }}
          />
          <Btn
            title='Bottom -'
            onClick={() => {
              setMargin({ ...margin, bottom: margin.bottom - 4 })
            }}
          />
        </div>
      </div>
    </div>
  )
}

export default MarginWrapper

const Btn = ({ title, onClick }: { title: string; onClick: () => void }) => {
  return <button onClick={onClick}>{title}</button>
}
